    ) {
        @Serdeable
        data class WorkgroupSummary(
            val id: Long,
            val name: String
        )

        @Serdeable
        data class TagSummary(
            val key: String,
            val value: String
        )

        companion object {
            fun from(asset: Asset): AssetResponse {
                // Access workgroups safely - may be lazy-loaded
                val workgroupSummaries = try {
                    asset.workgroups.map { WorkgroupSummary(it.id!!, it.name) }
                } catch (e: Exception) {
                    null
                }

                val tagSummaries = try {
                    asset.tags.map { TagSummary(it.key, it.value) }
                } catch (e: Exception) {
                    null
                }

                return AssetResponse(
                    id = asset.id!!,
                    name = asset.name,
                    crowdStrikeHostname = asset.crowdStrikeHostname,
                    nameOverridden = asset.nameOverriddenAt != null,
                    nameOverriddenAt = asset.nameOverriddenAt?.toString(),
                    nameOverriddenBy = asset.nameOverriddenBy,
                    type = asset.type,
                    ip = asset.ip,
                    ipAddresses = (asset.ipAddresses + listOfNotNull(asset.ip)).distinct().sorted(),
                    uri = asset.uri,
                    owner = asset.owner,
                    description = asset.description,
                    lastSeen = asset.lastSeen?.toString(),
                    groups = asset.groups,
                    criticality = asset.criticality,
                    cloudAccountId = asset.cloudAccountId,
                    cloudInstanceId = asset.cloudInstanceId,
                    adDomain = asset.adDomain,
                    osVersion = asset.osVersion,
                    createdAt = asset.createdAt?.toString(),
                    workgroups = workgroupSummaries,
                    networkZone = asset.networkZone,
                    openPortCount = asset.openPortCount,
                    lastScanType = asset.lastScanType,
                    lastScanDate = asset.lastScanDate?.toString(),
                    tags = tagSummaries
                )
            }
        }
    }

    private fun normalizeUri(value: String?): String? {
        val trimmed = value?.trim()?.takeIf { it.isNotBlank() } ?: return null
        require(trimmed.length <= 2048) { "URI must not exceed 2048 characters" }
        val parsed = URI.create(trimmed)
        val scheme = parsed.scheme?.lowercase()
        require(!scheme.isNullOrBlank()) { "URI must include a scheme, such as https:// or urn:" }
        require(scheme in setOf("http", "https", "urn")) { "URI scheme must be http, https, or urn" }
        require(!(scheme in setOf("http", "https") && parsed.host.isNullOrBlank())) { "HTTP(S) URI must include a host" }
        return trimmed
    }

