    open fun search(
        authentication: Authentication,
        @QueryValue(defaultValue = "0") page: Int,
        @QueryValue(defaultValue = "50") pageSize: Int,
        @Nullable @QueryValue name: String?,
        @Nullable @QueryValue ip: String?,
        @Nullable @QueryValue owner: String?,
        @Nullable @QueryValue adDomain: String?,
        @Nullable @QueryValue accountId: String?,
        @Nullable @QueryValue workgroupId: Long?
    ): HttpResponse<*> {
        if (page !in 0..MAX_OVERVIEW_PAGE || pageSize !in ALLOWED_OVERVIEW_PAGE_SIZES) {
            return HttpResponse.badRequest(ErrorResponse("Page must be non-negative and pageSize must be 25, 50, 100, or 250"))
        }

        val filterValues = listOf(name, ip, owner, adDomain, accountId).map { it?.trim()?.takeIf(String::isNotEmpty) }
        val restrictedIds = if (GrantAuthority.canManage(authentication.roles)) null else {
            assetFilterService.getAccessibleAssetIds(authentication)
        }
        val result = assetOverviewQueryService.search(
            restrictedIds,
            com.secman.service.AssetOverviewQueryService.Filters(
                name = filterValues[0],
                ipAddress = filterValues[1],
                owner = filterValues[2],
                adDomain = filterValues[3],
                accountId = filterValues[4],
                workgroupId = workgroupId
            ),
            page,
            pageSize
        )

        return HttpResponse.ok(
            AssetOverviewResponse(
                items = result.assets.map(AssetOverviewRow::from),
                matchingCount = result.total,
                page = page,
                pageSize = pageSize,
                totalPages = if (result.total == 0L) 0 else ((result.total + pageSize - 1) / pageSize).toInt()
            )
        )
    }

    /**
     * Count all assets in the system without loading asset rows.
     * Used by dashboard summary cards where a global inventory count is desired.
     */
    @Get("/count")
    @Transactional(readOnly = true)
    open fun countAll(authentication: Authentication): HttpResponse<AssetCountResponse> {
        val count = if (com.secman.security.GrantAuthority.canManage(authentication.roles)) {
            assetRepository.count()
        } else assetFilterService.getAccessibleAssetIds(authentication).size.toLong()
        return HttpResponse.ok(AssetCountResponse(count))
    }

    companion object {
        private const val MAX_OVERVIEW_PAGE = 100_000
        private val ALLOWED_OVERVIEW_PAGE_SIZES = setOf(25, 50, 100, 250)
    }

    /**
     * Get internet-facing assets (EXTERNAL or DMZ network zone) that have an IP address.
     * Used by the CLI port-scan command to determine scan targets.
     *
     * GET /api/assets/internet-facing
     * Auth: ADMIN role required (port scanning is an admin operation)
     */
    @Get("/internet-facing")
    @Secured("ADMIN")
    @Transactional(readOnly = true)
    open fun getInternetFacingAssets(): HttpResponse<List<AssetResponse>> {
        return try {
            log.debug("Fetching internet-facing assets")
            val assets = assetRepository.findInternetFacingWithIp()
                .map { AssetResponse.from(it) }
            log.debug("Found {} internet-facing assets", assets.size)
            HttpResponse.ok(assets)
        } catch (e: Exception) {
            log.error("Error fetching internet-facing assets", e)
            HttpResponse.serverError<List<AssetResponse>>()
        }
    }

    /**
     * Get asset by ID with access control
     *
     * FR-020: Verify asset access before detail view
     */
    @Get("/{id}")
    @Transactional(readOnly = true)
    open fun get(id: Long, authentication: Authentication): HttpResponse<*> {
        return try {
            log.debug("Fetching asset with id: {} for user: {}", id, authentication.name)

            val asset = assetRepository.findById(id).orElse(null)

            if (asset == null) {
                log.debug("Asset not found with id: {}", id)
                return HttpResponse.notFound(ErrorResponse("Asset not found"))
            }

            // Check if user can access this asset (workgroup-based access control)
            if (!assetFilterService.canAccessAsset(id, authentication)) {
                log.warn("User {} denied access to asset {}", authentication.name, id)
                return HttpResponse.notFound(ErrorResponse("Asset not found"))
            }

            log.debug("Found asset: {}", asset.name)
            HttpResponse.ok(AssetResponse.from(asset))
        } catch (e: Exception) {
            log.error("Error fetching asset with id: {}", id, e)
            HttpResponse.serverError<Any>()
        }
    }

    /**
     * Get asset by name with access control
     * Used by CrowdStrike Vulnerability Lookup to load asset details for editing.
     */
    @Get("/by-name/{name}")
    @Transactional(readOnly = true)
    open fun getByName(name: String, authentication: Authentication): HttpResponse<*> {
        return try {
            log.debug("Fetching asset by name: {} for user: {}", name, authentication.name)

            val asset = assetRepository.findByCrowdStrikeHostnameIgnoreCase(name)
                ?: assetRepository.findByNameIgnoreCase(name)

            if (asset == null) {
                return HttpResponse.notFound(ErrorResponse("Asset not found"))
            }

            if (!assetFilterService.canAccessAsset(asset.id!!, authentication)) {
                log.warn("User {} denied access to asset {}", authentication.name, name)
                return HttpResponse.notFound(ErrorResponse("Asset not found"))
            }

            HttpResponse.ok(AssetResponse.from(asset))
        } catch (e: Exception) {
            log.error("Error fetching asset by name: {}", name, e)
            HttpResponse.serverError<Any>()
        }
    }

