import io.micronaut.serde.annotation.Serdeable
import jakarta.validation.constraints.NotBlank
import jakarta.validation.constraints.NotNull
import java.time.LocalDateTime

/**
 * DTO representing a vulnerability from CrowdStrike Falcon API
 */
@Serdeable
data class CrowdStrikeVulnerabilityDto(
    /**
     * Unique vulnerability ID from CrowdStrike
     */
    @field:NotBlank
    val id: String,

    /**
     * System hostname
     */
    @field:NotBlank
    val hostname: String,

    /**
     * System IP address (nullable)
     */
    val ip: String?,

    /** All network addresses reported for the Falcon device. */
    val ipAddresses: Set<String> = emptySet(),

    /**
     * Active Directory domain (nullable)
     */
    val adDomain: String? = null,

    /**
     * Operating system / OS version reported by CrowdStrike (nullable)
     * Source: host_info.os_version (falls back to host_info.platform)
     */
    val osVersion: String? = null,

    /**
     * CVE identifier (nullable)
     */
    val cveId: String?,

    /**
     * CVSS severity level (Critical, High, Medium, Low, Informational)
     */
    @field:NotBlank
    val severity: String,

    /**
     * Numeric CVSS score (0.0-10.0, nullable)
     */
    val cvssScore: Double?,

    /**
     * Vulnerable product and version (nullable)
     */
    val affectedProduct: String?,

    /**
     * Days since detection (calculated, e.g., "15 days")
     */
    val daysOpen: String?,

    /**
     * When Falcon created this finding for this host, or **null when the API did not
     * publish a readable one**.
     *
     * Nullable on purpose. Substituting "now" for an unknown detection date makes the
     * finding look zero days old, which keeps it out of every overdue calculation —
     * a silent security miss dressed as a formatting fallback. Unknown must stay
     * unknown all the way to the reader; see [FalconTimestamps].
     */
    val detectedAt: LocalDateTime?,

    /**
     * Best available "a fix existed from" date (nullable).
     *
     * Prefers a genuine vendor/remediation release date and only falls back to the
     * CVE publication date when no remediation date is published. The fallback is
     * deliberate: `secman.vulnerability.require-patch-publication-date` filters
     * imports on this field being non-null, so narrowing it to true patch dates
     * only would silently drop rows.
     *
     * When you specifically need "when was the CVE disclosed", read
     * [cvePublishedDate] instead — do not infer it from this field.
     */
    val patchPublicationDate: LocalDateTime? = null,

    /**
     * CVE publication (disclosure) date, from `cve.published_date` / `cve.published`.
     *
     * Distinct from both [detectedAt] (when Falcon created the finding for this host)
     * and [patchPublicationDate] (when a fix became available). Reported separately
     * because a reader looking at "CVE-2023-…" reasonably expects to see 2023, and
     * neither of the other two dates carries that meaning.
     */
    val cvePublishedDate: LocalDateTime? = null,

    /**
     * Vulnerability status (always "open" for this query)
     */
    @field:NotBlank
    val status: String,

    /**
     * Whether this vulnerability matches an active exception
     */
    @field:NotNull
    val hasException: Boolean,

    /**
     * Reason for exception if hasException is true (nullable)
     */
    val exceptionReason: String? = null,

    /**
     * Cloud provider account ID (e.g., AWS account ID)
     */
    val cloudAccountId: String? = null,

    /**
     * Cloud instance ID (e.g., AWS EC2 instance ID)
     */
    val cloudInstanceId: String? = null,

    /** Falcon agent identifier used to keep asset identity stable across hostname changes. */
    val crowdStrikeAid: String? = null
)

/**
 * IP address to store on the asset for a host's vulnerability rows.
 *
 * CrowdStrike returns one row per (host, CVE) and `local_ip` rides on the per-row host_info
 * facet, so a single row can be missing the IP while its siblings carry it. Reading only the
 * first row therefore drops an IP that does exist, and the asset - and every export of it -
 * ends up blank. Mirrors how cloudInstanceId/osVersion are already resolved by the callers.
 */
fun List<CrowdStrikeVulnerabilityDto>.resolveHostIps(): Set<String> =
    flatMap { vuln -> vuln.ipAddresses + listOfNotNull(vuln.ip) }
        .map(String::trim)
        .filter(String::isNotBlank)
        .toSortedSet()

fun List<CrowdStrikeVulnerabilityDto>.resolveHostIp(): String? = resolveHostIps().firstOrNull()
