        every { vulnerabilityRepository.findByAssetId(any(), any()) } returns Page.empty()
        every { vulnerabilityRepository.deleteByAssetId(any()) } returns 0
        // Post-import per-asset excepted recompute flushes before the native recompute runs.
        every { entityManager.flush() } just Runs
        every { crowdStrikeAssetIdentityRepository.findByCrowdStrikeAidIn(any()) } returns emptyList()
    }

