            savedAssetSlot.captured.apply { id = 11L }
        }
        every {
            entityManager.find(Asset::class.java, 11L, jakarta.persistence.LockModeType.PESSIMISTIC_WRITE)
        } answers {
            savedAssetSlot.captured
        }

        service.importVulnerabilitiesForServer(batch("server-1"))

        assertThat(savedAssetSlot.captured.crowdStrikeLastImportedAt).isNotNull()
        assertThat(savedAssetSlot.captured.crowdStrikeHostname).isEqualTo("server-1")
    }

