package com.secman.repository

import com.secman.domain.Asset
import com.secman.domain.Criticality
import com.secman.domain.Workgroup
import com.secman.testutil.BaseIntegrationTest
import com.secman.testutil.TestDataFactory
import io.micronaut.test.extensions.junit5.annotation.MicronautTest
import jakarta.inject.Inject
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.AfterEach
import org.junit.jupiter.api.Test

/**
 * Regression test for the row *shape* returned by
 * [AssetRepository.findWorkgroupIdsByAssetIds].
 *
 * The method used to be declared with `nativeQuery = true`, which made Micronaut Data
 * hand back one-element rows even though the query selected two columns. The only
 * caller — MaterializedViewRefreshService.loadWorkgroupIdsByAsset — reads `row[1]`,
 * so every materialized-view refresh over an asset that actually had a workgroup
 * died with `ArrayIndexOutOfBoundsException: Index 1 out of bounds for length 1`.
 * Assets without workgroups returned zero rows and never tripped it, which is why
 * this hid behind a single test.
 *
 * These assertions lock the two-column contract itself, not just "the caller happens
 * to work": converting the query back to a native one fails `hasSize(2)` immediately.
 *
 * `transactional = false` follows the precedent in [AssetRepositoryLegacyStaleTest] —
 * the rows must really be committed for the projection to see them.
 */
@MicronautTest(environments = ["test"], transactional = false)
open class AssetRepositoryWorkgroupIdsProjectionTest : BaseIntegrationTest() {

    @Inject
    lateinit var assetRepository: AssetRepository

    @Inject
    lateinit var workgroupRepository: WorkgroupRepository

    private var asset: Asset? = null
    private val workgroups = mutableListOf<Workgroup>()

    @AfterEach
    fun tearDown() {
        asset?.let { assetRepository.delete(it) }
        workgroups.forEach { workgroupRepository.delete(it) }
        asset = null
        workgroups.clear()
    }

    @Test
    fun `returns two-column rows pairing each asset id with each of its workgroup ids`() {
        val suffix = System.nanoTime()

        val wgA = workgroupRepository.save(Workgroup(name = "wg-a-$suffix", criticality = Criticality.HIGH))
        val wgB = workgroupRepository.save(Workgroup(name = "wg-b-$suffix", criticality = Criticality.LOW))
        workgroups += listOf(wgA, wgB)

        val toSave = TestDataFactory.createAsset(name = "wg-projection-asset-$suffix", owner = "owner-$suffix")
        toSave.workgroups = mutableSetOf(wgA, wgB)
        asset = assetRepository.save(toSave)

        val assetId = asset!!.id!!
        val rows = assetRepository.findWorkgroupIdsByAssetIds(listOf(assetId))

        // One row per (asset, workgroup) pair.
        assertThat(rows).hasSize(2)

        // The actual regression: each row must carry BOTH selected columns.
        rows.forEach { row -> assertThat(row).hasSize(2) }

        val pairs = rows.map { (it[0] as Number).toLong() to (it[1] as Number).toLong() }
        assertThat(pairs).containsExactlyInAnyOrder(
            assetId to wgA.id!!,
            assetId to wgB.id!!
        )
    }

    @Test
    fun `returns no rows for an asset with no workgroups`() {
        val suffix = System.nanoTime()

        val toSave = TestDataFactory.createAsset(name = "wg-less-asset-$suffix", owner = "owner-$suffix")
        asset = assetRepository.save(toSave)

        assertThat(assetRepository.findWorkgroupIdsByAssetIds(listOf(asset!!.id!!))).isEmpty()
    }

    @Test
    fun `omits disabled workgroups from materialized access rows`() {
        val suffix = System.nanoTime()
        val enabled = workgroupRepository.save(
            Workgroup(name = "wg-enabled-$suffix", criticality = Criticality.HIGH)
        )
        val disabled = workgroupRepository.save(
            Workgroup(name = "wg-disabled-$suffix", criticality = Criticality.LOW, enabled = false)
        )
        workgroups += listOf(enabled, disabled)

        val toSave = TestDataFactory.createAsset(name = "wg-status-asset-$suffix", owner = "owner-$suffix")
        toSave.workgroups = mutableSetOf(enabled, disabled)
        asset = assetRepository.save(toSave)

        val rows = assetRepository.findWorkgroupIdsByAssetIds(listOf(asset!!.id!!))
        val workgroupIds = rows.map { (it[1] as Number).toLong() }

        assertThat(workgroupIds).containsExactly(enabled.id!!)
    }
}
import { test, expect, type Page } from '@playwright/test';

const admin = { id: 1, username: 'adminuser', email: 'admin@example.com', roles: ['ADMIN'] };
const group = { id: 42, name: 'AWS-Example', description: 'Example team', enabled: false, criticality: 'HIGH', ownerEmail: 'owner@example.com' };

async function prepare(page: Page, empty = false) {
  const login = await page.request.post('/api/auth/login', {
    data: { username: process.env.SECMAN_ADMIN_NAME!, password: REDACTED },
  });
  expect(login.ok()).toBeTruthy();
  await page.addInitScript(user => sessionStorage.setItem('user', JSON.stringify(user)), admin);
  await page.route('**/api/**', async route => {
    const url = new URL(route.request().url());
    let body: unknown;
    if (url.pathname === '/api/auth/status') body = admin;
    if (url.pathname === '/api/users') body = [{ ...admin, workgroups: [group, { id: 43, name: 'Another team' }] }];
    if (url.pathname === '/api/workgroups') body = [group];
    if (url.pathname === '/api/workgroups/42') body = group;
    if (url.pathname === '/api/workgroups/42/users') body = empty ? [] : [{ id: 2, username: 'member', email: 'member@example.com' }];
    if (url.pathname === '/api/workgroups/42/assets') body = empty ? [] : [{ id: 3, name: 'app-server', type: 'SERVER', ip: '192.0.2.10', owner: 'Example owner' }];
    if (url.pathname === '/api/workgroups/42/aws-accounts') body = empty ? [] : [{ id: 4, awsAccountId: '123456789012' }];
    if (url.pathname === '/api/workgroups/42/ad-domains') body = empty ? [] : [{ id: 5, adDomain: 'corp.example.com' }];
    if (body === undefined) return route.continue();
    await route.fulfill({ contentType: 'application/json', body: JSON.stringify(body) });
  });
  await page.goto('/admin/user-management');
  await page.getByRole('button', { name: group.name, exact: true }).click();
  return page.getByRole('dialog', { name: `Workgroup Details — ${group.name}` });
}

test('workgroup badge opens all assigned details in place and restores focus on Escape', async ({ page }, testInfo) => {
  const dialog = await prepare(page);
  await expect(dialog).toBeVisible();
  await expect(page).toHaveURL(/\/admin\/user-management$/);
  await expect(dialog.getByText('Disabled', { exact: true })).toBeVisible();
  await expect(dialog.getByText('owner@example.com', { exact: true })).toBeVisible();
  await expect(dialog.getByRole('region', { name: 'Users (1)' })).toContainText('member@example.com');
  const assets = dialog.getByRole('region', { name: 'Assets (1)' });
  await expect(assets).toContainText('app-server');
  await expect(assets).toContainText('192.0.2.10');
  await expect(assets).toContainText('Example owner');
  await expect(dialog.getByRole('region', { name: 'AWS Accounts (1)' })).toContainText('123456789012');
  await expect(dialog.getByRole('region', { name: 'AD Domains (1)' })).toContainText('corp.example.com');
  await expect(dialog.getByRole('link', { name: 'Open Workgroup Management' })).toHaveAttribute('href', '/workgroups?workgroupId=42');
  await page.screenshot({ path: testInfo.outputPath('workgroup-details.png') });
  await page.keyboard.press('Escape');
  await expect(dialog).toHaveCount(0);
  await expect(page.getByRole('button', { name: group.name, exact: true })).toBeFocused();
});

test('empty assignments are shown explicitly', async ({ page }) => {
  const dialog = await prepare(page, true);
  for (const message of ['No users assigned.', 'No assets directly assigned.', 'No AWS accounts assigned.', 'No AD domains assigned.']) {
    await expect(dialog.getByText(message, { exact: true })).toBeVisible();
  }
});

test('failed section cannot look empty and can be retried', async ({ page }) => {
  const dialog = await prepare(page);
  await dialog.getByRole('button', { name: 'Close', exact: true }).click();
  await page.route('**/api/workgroups/42/ad-domains', route => route.fulfill({ status: 500, body: '{}' }));
  await page.getByRole('button', { name: group.name, exact: true }).click();
  await expect(dialog.getByRole('alert')).toContainText('Could not load all workgroup details');
  await expect(dialog.getByText('No AD domains assigned.')).toHaveCount(0);
  await page.unroute('**/api/workgroups/42/ad-domains');
  await dialog.getByRole('button', { name: 'Retry' }).click();
  await expect(dialog.getByRole('region', { name: 'AD Domains (1)' })).toContainText('corp.example.com');
});

test('denied workgroup details do not render assignments', async ({ page }) => {
  const dialog = await prepare(page);
  await dialog.getByRole('button', { name: 'Close', exact: true }).click();
  await page.route('**/api/workgroups/42', route => route.fulfill({ status: 403, body: '{}' }));
  await page.getByRole('button', { name: group.name, exact: true }).click();
  await expect(dialog.getByRole('alert')).toContainText('You do not have permission');
  await expect(dialog.getByRole('region')).toHaveCount(0);
});
