                    owner = it.owner
                )
            }
            HttpResponse.ok(assets)
        } catch (e: IllegalArgumentException) {
            HttpResponse.status<Map<String, String>>(io.micronaut.http.HttpStatus.NOT_FOUND)
                .body(mapOf("error" to (e.message ?: "Workgroup not found")))
        }
    }

