                    assetName = try { ra.getAssetName() } catch (_: Exception) { "Unknown" },
                    status = ra.status,
                    assessor = ra.assessor.username,
                    startDate = ra.startDate.toString(),
                    endDate = ra.endDate.toString()
                )
            }

        // High priority risks (level >= 3)
