                name = risk.name,
                description = risk.description ?: "",
                assetName = risk.asset?.name ?: "Unknown",
                riskLevel = risk.riskLevel ?: 0,
                status = risk.status,
                owner = risk.owner?.username ?: "Unassigned",
                severity = risk.severity ?: "Unknown",
