 * one HTTP request.
 *
 * `@RequestScope` gives us exactly that lifetime: the bean is constructed on
 * first inject and torn down at end of request, so cache pollution between
 * users / requests is structurally impossible.
 *
 * Thread-safety: `@RequestScope` beans live on a single request thread, so we
 * do not need synchronization. (If a request later spawns coroutines or
 * background work, those should not consult this cache; they have a different
 * authentication context anyway.)
 */
@RequestScope
open class AccessibleAssetIdsCache(
    private val assetFilterService: AssetFilterService
) {
    private var cached: Set<Long>? = null
    private var cachedForUserId: Long? = null

    /**
     * Return the user's accessible asset-ID set, computing it on first call
     * within this request and reusing the same result on subsequent calls.
     *
     * The userId guard is defensive: if the same request impersonates a
     * different identity (it should not, but the framework allows
     * authentication.swap-style flows in principle), we recompute rather than
     * serve a cached set for the wrong user.
     */
    fun get(authentication: Authentication): Set<Long> {
        val currentUserId = authentication.attributes["userId"]?.toString()?.toLongOrNull()
        val cachedSnapshot = cached
        if (cachedSnapshot != null && cachedForUserId == currentUserId) {
            return cachedSnapshot
        }
        val ids = assetFilterService.getAccessibleAssetIds(authentication)
        cached = ids
        cachedForUserId = currentUserId
        return ids
    }
}
package com.secman.controller

import com.secman.domain.AwsAccount
import com.secman.repository.AwsAccountRepository
import com.secman.repository.RiskAssessmentRepository
import com.secman.domain.AssessmentBasisType
import io.micronaut.http.HttpResponse
import io.micronaut.http.annotation.Body
import io.micronaut.http.annotation.Controller
import io.micronaut.http.annotation.Delete
import io.micronaut.http.annotation.PathVariable
import io.micronaut.http.annotation.Put
import io.micronaut.scheduling.TaskExecutors
import io.micronaut.scheduling.annotation.ExecuteOn
import io.micronaut.security.annotation.Secured
import io.micronaut.security.authentication.Authentication
import io.micronaut.serde.annotation.Serdeable
import io.micronaut.transaction.annotation.Transactional
import org.slf4j.LoggerFactory

/**
 * Admin-editable display names for AWS accounts.
 *
 * Rows are created lazily on first name assignment. A blank name clears the stored
 * name, which makes the account fall back to its bare 12-digit ID in every report.
 */
@Controller("/api/admin/aws-accounts")
@Secured("ADMIN")
@ExecuteOn(TaskExecutors.BLOCKING)
open class AwsAccountController(
    private val awsAccountRepository: AwsAccountRepository,
    private val riskAssessmentRepository: RiskAssessmentRepository
) {
    private val logger = LoggerFactory.getLogger(AwsAccountController::class.java)

    private val accountIdPattern = Regex("^\\d{12}$")

    @Serdeable
    data class UpdateNameRequest(val name: String?)

    @Serdeable
    data class AwsAccountNameResponse(val awsAccountId: String, val name: String?)

    @Serdeable
    data class ErrorResponse(val message: String)

    @Put("/{awsAccountId}/name")
    @Transactional
    open fun updateName(
        @PathVariable awsAccountId: String,
        @Body request: UpdateNameRequest,
        authentication: Authentication
    ): HttpResponse<*> {
        if (!accountIdPattern.matches(awsAccountId)) {
            return HttpResponse.badRequest(ErrorResponse("AWS Account ID must be exactly 12 numeric digits"))
        }

        val cleaned = request.name?.trim()?.ifBlank { null }

        return try {
            val existing = awsAccountRepository.findByAwsAccountId(awsAccountId)
            val saved = if (existing.isPresent) {
                val row = existing.get()
                row.name = cleaned
                row.updatedBy = authentication.name
                awsAccountRepository.update(row)
            } else {
                awsAccountRepository.save(
                    AwsAccount(awsAccountId = awsAccountId, name = cleaned, updatedBy = authentication.name)
                )
            }
            logger.info("AWS account {} renamed to '{}' by {}", awsAccountId, cleaned, authentication.name)
            HttpResponse.ok(AwsAccountNameResponse(saved.awsAccountId, saved.name))
        } catch (e: Exception) {
            logger.error("Failed to update name for AWS account {}", awsAccountId, e)
            HttpResponse.serverError(ErrorResponse("Internal server error"))
        }
    }

    /** Delete only a nameless, unreferenced account row (used by exact fixture cleanup). */
    @Delete("/{awsAccountId}")
    @Transactional
    open fun deleteUnreferenced(@PathVariable awsAccountId: String): HttpResponse<*> {
        if (!accountIdPattern.matches(awsAccountId)) {
            return HttpResponse.badRequest(ErrorResponse("AWS Account ID must be exactly 12 numeric digits"))
        }
        val account = awsAccountRepository.findByAwsAccountId(awsAccountId).orElse(null)
            ?: return HttpResponse.notFound<ErrorResponse>()
        if (account.name != null || riskAssessmentRepository.existsByAssessmentBasisTypeAndAssessmentBasisId(
                AssessmentBasisType.AWS_ACCOUNT,
                account.id!!
            )
        ) {
            return HttpResponse.status<ErrorResponse>(io.micronaut.http.HttpStatus.CONFLICT)
                .body(ErrorResponse("AWS account is named or still referenced"))
        }
        awsAccountRepository.delete(account)
        logger.info("Deleted unreferenced nameless AWS account {}", awsAccountId)
        return HttpResponse.noContent<Any>()
    }
}

