package com.secman.service

import com.secman.domain.Asset
import com.secman.domain.Workgroup
import com.secman.dto.AssetVulnCountDto
import com.secman.dto.CrowdStrikeImportStatusDto
import com.secman.dto.WorkgroupGroupDto
import com.secman.dto.WorkgroupVulnsSummaryDto
import com.secman.dto.AssetInterventionStatus
import com.secman.repository.AssetRepository
import com.secman.repository.VulnerabilityRepository
import com.secman.repository.WorkgroupRepository
import com.secman.repository.CrowdStrikeImportHistoryRepository
import com.secman.repository.WorkgroupAwsAccountRepository
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Singleton
import org.slf4j.LoggerFactory
import java.time.LocalDateTime

/**
 * Service for retrieving vulnerability summaries grouped by workgroup.
 *
 * Provides business logic for the WG Vulns view, including:
 * - Looking up user's workgroup memberships
 * - Filtering assets by workgroup IDs
 * - Counting vulnerabilities per asset
 * - Grouping and sorting results
 *
 * Access Control:
 * - Admin users are rejected (should use System Vulns instead)
 * - Non-admin users see assets from their workgroups (direct membership) AND
 *   assets whose cloudAccountId matches an AWS account assigned to one of their
 *   workgroups via WorkgroupAwsAccount (Unified Asset Access rule #9).
 */
@Singleton
class WorkgroupVulnsService(
    private val workgroupRepository: WorkgroupRepository,
    private val assetRepository: AssetRepository,
    private val vulnerabilityRepository: VulnerabilityRepository,
    private val assetVulnCountsQuery: AssetVulnCountsQuery,
    private val importHistoryRepository: CrowdStrikeImportHistoryRepository,
    private val workgroupAdDomainRepository: com.secman.repository.WorkgroupAdDomainRepository,
    private val workgroupAwsAccountRepository: WorkgroupAwsAccountRepository
) {

    private val logger = LoggerFactory.getLogger(WorkgroupVulnsService::class.java)

    /**
     * Get vulnerability summary for the authenticated user's workgroups.
     *
     * @param authentication User authentication details (email + roles)
     * @return WorkgroupVulnsSummaryDto with workgroup groups, assets, and vulnerability counts
     * @throws IllegalStateException if user has ADMIN role or email not found in authentication
     * @throws NoSuchElementException if user has no workgroup memberships
     */
    fun getWorkgroupVulnsSummary(authentication: Authentication): WorkgroupVulnsSummaryDto {
        // Extract email from authentication attributes
        val userEmail = authentication.attributes["email"]?.toString()
            ?: throw IllegalStateException("Email not found in authentication context")
        val roles = authentication.roles

        logger.debug("Getting workgroup vulns summary for user: {} (username: {})", userEmail, authentication.name)

        // Check if user is admin - reject with error
        if (roles.contains("ADMIN")) {
            logger.warn("Admin user {} attempted to access WG Vulns view", userEmail)
            throw IllegalStateException("Admin users should use System Vulns view instead")
        }

        // Only enabled direct memberships participate in this grouped view.
        val userWorkgroups = workgroupRepository.findWorkgroupsByUserEmail(userEmail)

        // Check if user has any workgroup memberships
        if (userWorkgroups.isEmpty()) {
            logger.warn("User {} has no workgroup memberships", userEmail)
            throw NoSuchElementException("You are not a member of any workgroups. Please contact your administrator.")
        }

        logger.debug("User {} is a member of {} workgroups", userEmail, userWorkgroups.size)

        // Get workgroup IDs
        val workgroupIds = userWorkgroups.mapNotNull { it.id }

        // Direct-membership assets (asset ↔ workgroup join). The repository query
        // uses LEFT JOIN FETCH on workgroups, so asset.workgroups is safe to read.
        val directAssets = assetRepository.findByWorkgroupIdIn(workgroupIds)
        val directAssetIds = directAssets.mapNotNullTo(HashSet()) { it.id }

        // Unified Asset Access rule #9: assets in AWS accounts assigned to the
        // user's workgroups (WorkgroupAwsAccount, direct workgroup membership only).
        // Build workgroupId -> set<awsAccountId> so we can also map each EC2 asset
        // back to the workgroup column it should appear under.
        val workgroupToAwsAccounts: Map<Long, Set<String>> = workgroupIds.associateWith { wgId ->
            workgroupAwsAccountRepository.findByWorkgroupId(wgId)
                .map { it.awsAccountId }
                .toSet()
        }
        val allWorkgroupCloudAccountIds = workgroupToAwsAccounts.values
            .flatten()
            .distinct()
        val cloudAssets = if (allWorkgroupCloudAccountIds.isNotEmpty()) {
            assetRepository.findByCloudAccountIdIn(allWorkgroupCloudAccountIds)
        } else {
            emptyList()
        }

        // distinctBy keeps the first occurrence — directAssets first ensures the
        // version with the eagerly-fetched workgroups collection wins, avoiding
        // a lazy read on cloud-only assets later.
        val domainsByGroup = workgroupAdDomainRepository.findByWorkgroupIdIn(workgroupIds)
            .groupBy({ it.workgroup.id!! }, { it.adDomain.lowercase() })
        val domains = domainsByGroup.values.flatten().distinct()
        val domainAssets = if (domains.isEmpty()) emptyList() else assetRepository.findByAdDomainInIgnoreCase(domains)
        val assets = (directAssets + cloudAssets + domainAssets).distinctBy { it.id }

        logger.debug(
            "Found {} assets for user {} ({} direct, {} via workgroup AWS accounts) across {} workgroups",
            assets.size, userEmail, directAssets.size, cloudAssets.size, userWorkgroups.size
        )

        // Get severity counts for all assets
        val assetIds = assets.mapNotNull { it.id }
        // One threshold instant for the whole response, so every asset is measured from the same
        // moment. Shared with the Account Vulns view via AssetVulnCountsQuery — this view
        // previously had its own copy of the query that omitted the exception columns entirely.
        val thresholdDays = assetVulnCountsQuery.thresholdDays()
        val thresholdDate = LocalDateTime.now().minusDays(thresholdDays.toLong())
        val severityCountsMap = assetVulnCountsQuery.countByAsset(assetIds, thresholdDate)

        // Map every accessible asset to the user-workgroups it should appear under.
        // For direct-membership assets we read asset.workgroups (fetched eagerly).
        // For cloud-only assets we MUST NOT read asset.workgroups (lazy proxy from
        // findByCloudAccountIdIn) — match via cloudAccountId instead.
        val workgroupById: Map<Long, Workgroup> = userWorkgroups.associateBy { it.id!! }
        val assetWorkgroups: Map<Long, List<Workgroup>> = assets.mapNotNull { asset ->
            val id = asset.id ?: return@mapNotNull null
            val directWgs: List<Workgroup> = if (id in directAssetIds) {
                asset.workgroups.filter { it.id in workgroupIds }
            } else {
                emptyList()
            }
            val cloudWgs: List<Workgroup> = asset.cloudAccountId?.let { cid ->
                workgroupToAwsAccounts
                    .filterValues { cid in it }
                    .keys
                    .mapNotNull { workgroupById[it] }
            } ?: emptyList()
            val domainWgs = asset.adDomain?.lowercase()?.let { domain ->
                domainsByGroup.filterValues { domain in it }.keys.mapNotNull { workgroupById[it] }
            }.orEmpty()
            id to (directWgs + cloudWgs + domainWgs).distinctBy { it.id }
        }.toMap()

        val assetsByWorkgroup: Map<Workgroup, List<Asset>> = userWorkgroups.associateWith { wg ->
            assets.filter { asset -> assetWorkgroups[asset.id]?.any { it.id == wg.id } == true }
        }

        // Build workgroup groups for ALL user's workgroups (including those with no assets)
        val workgroupGroups = userWorkgroups.map { workgroup ->
            val workgroupAssets = assetsByWorkgroup[workgroup] ?: emptyList()

            // Sort assets by vulnerability count (descending)
            val sortedAssets = workgroupAssets
                .map { asset ->
                    val assetId = asset.id!!
                    val severityCounts = severityCountsMap[assetId]

                    AssetVulnCountDto(
                        id = assetId,
                        name = asset.name,
                        type = asset.type,
                        vulnerabilityCount = severityCounts?.total ?: 0,
                        criticalCount = severityCounts?.critical,
                        highCount = severityCounts?.high,
                        mediumCount = severityCounts?.medium,
                        exceptedCount = severityCounts?.excepted,
                        nonExceptedCount = severityCounts?.nonExcepted,
                        nonExceptedOverdueCount = severityCounts?.nonExceptedOverdue,
                        status = severityCounts?.status ?: AssetInterventionStatus.GREEN
                    )
                }
                // Worst-first, vulnerability count as tie-break — same ordering as Account Vulns.
                .sortedWith(
                    compareByDescending<AssetVulnCountDto> { it.status?.ordinal ?: 0 }
                        .thenByDescending { it.vulnerabilityCount }
                )

            // Aggregate severity totals at workgroup level
            val totalCritical = sortedAssets.sumOf { it.criticalCount ?: 0 }
            val totalHigh = sortedAssets.sumOf { it.highCount ?: 0 }
            val totalMedium = sortedAssets.sumOf { it.mediumCount ?: 0 }
            val totalExcepted = sortedAssets.sumOf { it.exceptedCount ?: 0 }
            val totalNonExcepted = sortedAssets.sumOf { it.nonExceptedCount ?: 0 }
            val workgroupStatus = AssetInterventionStatus.worstOf(sortedAssets.mapNotNull { it.status })
            val needingAttention = sortedAssets.count {
                it.status != null && it.status != AssetInterventionStatus.GREEN
            }

            WorkgroupGroupDto(
                workgroupId = workgroup.id!!,
                workgroupName = workgroup.name,
                workgroupDescription = workgroup.description,
                assets = sortedAssets,
                totalAssets = sortedAssets.size,
                totalVulnerabilities = sortedAssets.sumOf { it.vulnerabilityCount },
                totalCritical = totalCritical,
                totalHigh = totalHigh,
                totalMedium = totalMedium,
                totalExcepted = totalExcepted,
                totalNonExcepted = totalNonExcepted,
                assetsNeedingAttention = needingAttention,
                status = workgroupStatus
            )
        }
        // Sort workgroup groups alphabetically by name
        .sortedBy { it.workgroupName }

        // Calculate overall totals (deduplicating assets that appear in multiple workgroups)
        val uniqueAssets = workgroupGroups.flatMap { it.assets }.distinctBy { it.id }
        val totalAssets = uniqueAssets.size
        val totalVulnerabilities = uniqueAssets.sumOf { it.vulnerabilityCount }

        // Calculate global severity totals (using unique assets)
        val globalCritical = uniqueAssets.sumOf { it.criticalCount ?: 0 }
        val globalHigh = uniqueAssets.sumOf { it.highCount ?: 0 }
        val globalMedium = uniqueAssets.sumOf { it.mediumCount ?: 0 }

        logger.debug(
            "Returning summary: {} workgroup groups, {} unique assets, {} total vulnerabilities " +
            "({} critical, {} high, {} medium)",
            workgroupGroups.size, totalAssets, totalVulnerabilities, 
            globalCritical, globalHigh, globalMedium
        )

        val latestImport = importHistoryRepository.findLatest()
            ?.let { CrowdStrikeImportStatusDto.fromEntity(it) }

        return WorkgroupVulnsSummaryDto(
            workgroupGroups = workgroupGroups,
            totalAssets = totalAssets,
            totalVulnerabilities = totalVulnerabilities,
            globalCritical = globalCritical,
            globalHigh = globalHigh,
            globalMedium = globalMedium,
            // Deduplicated: an asset in two workgroups must not count twice.
            globalExcepted = uniqueAssets.sumOf { it.exceptedCount ?: 0 },
            globalNonExcepted = uniqueAssets.sumOf { it.nonExceptedCount ?: 0 },
            globalStatus = AssetInterventionStatus.worstOf(uniqueAssets.mapNotNull { it.status }),
            assetsNeedingAttention = uniqueAssets.count {
                it.status != null && it.status != AssetInterventionStatus.GREEN
            },
            thresholdDays = thresholdDays,
            lastImport = latestImport
        )
    }
}
package com.secman.service

import com.secman.dto.AccountGroupDto
import com.secman.dto.AccountVulnsSummaryDto
import com.secman.dto.AssetInterventionStatus
import com.secman.dto.AssetVulnCountDto
import com.secman.dto.CrowdStrikeImportStatusDto
import com.secman.repository.UserMappingRepository
import com.secman.repository.VulnerabilityRepository
import com.secman.repository.CrowdStrikeImportHistoryRepository
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Singleton
import org.slf4j.LoggerFactory
import java.time.LocalDateTime

/**
 * Service for retrieving vulnerability summaries grouped by AWS account.
 *
 * Provides business logic for the Account Vulns view, including:
 * - Looking up user's AWS account mappings
 * - Filtering assets by AWS account IDs
 * - Counting vulnerabilities per asset
 * - Grouping and sorting results
 *
 * Access Control:
 * - Admin users are rejected (should use System Vulns instead)
 * - Non-admin users see the cloud assets they can access via the SAME unified
 *   10-point filter as the Current Vulnerabilities view (AssetFilterService),
 *   restricted to assets that carry a cloudAccountId and grouped by account.
 *   This keeps the two views' vulnerability counts reconcilable for every user.
 */
@Singleton
class AccountVulnsService(
    private val userMappingRepository: UserMappingRepository,
    private val assetFilterService: AssetFilterService,
    private val vulnerabilityRepository: VulnerabilityRepository,
    private val assetVulnCountsQuery: AssetVulnCountsQuery,
    private val importHistoryRepository: CrowdStrikeImportHistoryRepository,
    private val awsAccountSharingService: AwsAccountSharingService
) {

    private val logger = LoggerFactory.getLogger(AccountVulnsService::class.java)

    companion object {
        /**
         * Upper bound on cloud assets rendered in a single Account Vulns response.
         *
         * Exists because ADMIN/SECCHAMPION reach every asset: AssetFilterService.getAccessibleAssets
         * short-circuits to assetRepository.findAll() for them. One row per asset is unusable in a
         * browser long before this, so the cap fails loudly instead of quietly building a huge page.
         */
        internal const val MAX_RENDERED_ASSETS = 5000
    }

    /**
     * Get vulnerability summary for the authenticated user's AWS accounts.
     *
     * @param authentication User authentication details (email + roles)
     * @return AccountVulnsSummaryDto with account groups, assets, and vulnerability counts
     * @throws IllegalStateException if user has ADMIN role or email not found in authentication
     * @throws NoSuchElementException if user has no AWS account mappings
     */
    fun getAccountVulnsSummary(authentication: Authentication): AccountVulnsSummaryDto {
        // Extract email from authentication attributes (username is in authentication.name)
        val userEmail = authentication.attributes["email"]?.toString()
            ?: throw IllegalStateException("Email not found in authentication context")

        logger.debug("Getting account vulns summary for user: {} (username: {})", userEmail, authentication.name)

        // ADMIN is no longer rejected here: the intervention indicator is only useful if the people
        // who act on it can see it, and admins were previously bounced to System Vulnerabilities,
        // which has no asset-grouped overview. Access still flows through the same unified filter.

        // Account IDs the user is explicitly mapped to (UserMapping) or has shared
        // (AwsAccountSharing). Retained so that mapped-but-empty accounts still render
        // as account groups, matching the historical Account Vulns UX.
        val ownAwsAccountIds = userMappingRepository.findDistinctAwsAccountIdByEmail(userEmail)
        val sharedAwsAccountIds = awsAccountSharingService.getSharedAwsAccountIdsByEmail(userEmail)

        // Single source of truth for *which assets this user can see*: the same unified
        // 10-point filter used by the Current Vulnerabilities view (AssetFilterService).
        // Restricted to cloud assets since this view is organised by AWS account.
        // Using the shared filter guarantees the Account view and the Current view count
        // the same (asset, vulnerability) rows for every access path (workgroup, owner,
        // AD-domain, scan/manual upload, WorkgroupAwsAccount, sharing), not just direct
        // AWS account mappings.
        val assets = assetFilterService.getAccessibleAssets(authentication)
            .filter { !it.cloudAccountId.isNullOrBlank() }

        // ADMIN and SECCHAMPION reach every asset, so this view is only bounded for them by the
        // size of the estate. The response renders one row per asset and holds them all in memory,
        // so refuse up front with actionable guidance rather than building a payload no browser
        // can use. Scoped users are naturally bounded by their access and never hit this.
        if (assets.size > MAX_RENDERED_ASSETS) {
            logger.warn("Account Vulns refused for {}: {} cloud assets exceeds the {} cap",
                userEmail, assets.size, MAX_RENDERED_ASSETS)
            throw IllegalArgumentException(
                "This view would render ${assets.size} assets, above the $MAX_RENDERED_ASSETS limit. " +
                "Use System Vulnerabilities for estate-wide analysis."
            )
        }

        // Account groups = explicitly mapped/shared accounts (so empty accounts still show)
        // ∪ accounts that actually contain an accessible cloud asset.
        val awsAccountIds = (ownAwsAccountIds + sharedAwsAccountIds +
            assets.mapNotNull { it.cloudAccountId }).distinct()

        // 404 only when the user has neither AWS account mappings/shares nor any
        // accessible cloud asset to display.
        if (awsAccountIds.isEmpty()) {
            logger.warn("User {} has no AWS account mappings, shared accounts, or accessible cloud assets", userEmail)
            throw NoSuchElementException("No AWS accounts are mapped or shared with your user account. Please contact your administrator.")
        }

        logger.debug("User {} sees {} cloud assets across {} AWS accounts ({} own-mapped, {} shared)",
            userEmail, assets.size, awsAccountIds.size, ownAwsAccountIds.size, sharedAwsAccountIds.size)

        // Feature 019: Get severity counts for all assets
        val assetIds = assets.mapNotNull { it.id }
        // One threshold instant for the whole response, so every asset is measured from the same
        // moment and two assets cannot straddle the boundary because of clock drift mid-request.
        val thresholdDays = assetVulnCountsQuery.thresholdDays()
        val thresholdDate = LocalDateTime.now().minusDays(thresholdDays.toLong())
        val severityCountsMap = assetVulnCountsQuery.countByAsset(assetIds, thresholdDate)


        // Group assets by AWS account ID
        val assetsByAccount = assets.groupBy { it.cloudAccountId ?: "" }
            .filterKeys { it.isNotEmpty() }

        // Build account groups for ALL user's AWS accounts (including those with no assets)
        val accountGroups = awsAccountIds.map { awsAccountId ->
            val accountAssets = assetsByAccount[awsAccountId] ?: emptyList()

            // Sort assets by vulnerability count (descending)
            val sortedAssets = accountAssets
                .map { asset ->
                    val assetId = asset.id!!
                    val severityCounts = severityCountsMap[assetId]

                    AssetVulnCountDto(
                        id = assetId,
                        name = asset.name,
                        type = asset.type,
                        // Fix: Use severity counts total instead of lazy-loaded collection
                        vulnerabilityCount = severityCounts?.total ?: 0,
                        // Feature 019: Add severity breakdown
                        criticalCount = severityCounts?.critical,
                        highCount = severityCounts?.high,
                        mediumCount = severityCounts?.medium,
                        exceptedCount = severityCounts?.excepted,
                        nonExceptedCount = severityCounts?.nonExcepted,
                        nonExceptedOverdueCount = severityCounts?.nonExceptedOverdue,
                        // An asset with no vulnerability rows has no counts row at all, which is
                        // GREEN rather than unknown — there is nothing to act on.
                        status = severityCounts?.status ?: AssetInterventionStatus.GREEN
                    )
                }
                // Worst-first: RED assets surface at the top of each account, which is the whole
                // point of the indicator. Vulnerability count remains the tie-break.
                .sortedWith(
                    compareByDescending<AssetVulnCountDto> { it.status?.ordinal ?: 0 }
                        .thenByDescending { it.vulnerabilityCount }
                )

            // Feature 019: Aggregate severity totals at account level
            val totalCritical = sortedAssets.sumOf { it.criticalCount ?: 0 }
            val totalHigh = sortedAssets.sumOf { it.highCount ?: 0 }
            val totalMedium = sortedAssets.sumOf { it.mediumCount ?: 0 }
            val totalExcepted = sortedAssets.sumOf { it.exceptedCount ?: 0 }
            val totalNonExcepted = sortedAssets.sumOf { it.nonExceptedCount ?: 0 }
            val accountStatus = AssetInterventionStatus.worstOf(sortedAssets.mapNotNull { it.status })
            val needingAttention = sortedAssets.count {
                it.status != null && it.status != AssetInterventionStatus.GREEN
            }

            AccountGroupDto(
                awsAccountId = awsAccountId,
                assets = sortedAssets,
                totalAssets = sortedAssets.size,
                totalVulnerabilities = sortedAssets.sumOf { it.vulnerabilityCount },
                // Feature 019: Add account-level severity aggregation
                totalCritical = totalCritical,
                totalHigh = totalHigh,
                totalMedium = totalMedium,
                totalExcepted = totalExcepted,
                totalNonExcepted = totalNonExcepted,
                assetsNeedingAttention = needingAttention,
                status = accountStatus
            )
        }
        // Sort account groups by AWS account ID (ascending)
        .sortedBy { it.awsAccountId }

        // Calculate overall totals
        val totalAssets = accountGroups.sumOf { it.totalAssets }
        val totalVulnerabilities = accountGroups.sumOf { it.totalVulnerabilities }

        // Feature 019: Calculate global severity totals
        val globalCritical = accountGroups.sumOf { it.totalCritical ?: 0 }
        val globalHigh = accountGroups.sumOf { it.totalHigh ?: 0 }
        val globalMedium = accountGroups.sumOf { it.totalMedium ?: 0 }
        val globalExcepted = accountGroups.sumOf { it.totalExcepted ?: 0 }
        val globalNonExcepted = accountGroups.sumOf { it.totalNonExcepted ?: 0 }

        logger.debug("Returning summary: {} account groups (from {} mapped AWS accounts), {} total assets, {} total vulnerabilities " +
            "(Feature 019: {} critical, {} high, {} medium)",
            accountGroups.size, awsAccountIds.size, totalAssets, totalVulnerabilities, 
            globalCritical, globalHigh, globalMedium)

        val latestImport = importHistoryRepository.findLatest()
            ?.let { CrowdStrikeImportStatusDto.fromEntity(it) }

        // Compute actual data freshness from vulnerability import timestamps
        val dataFreshness = if (assetIds.isNotEmpty()) {
            vulnerabilityRepository.findLatestImportTimestampByAssetIds(assetIds.toSet())
        } else null

        return AccountVulnsSummaryDto(
            accountGroups = accountGroups,
            totalAssets = totalAssets,
            totalVulnerabilities = totalVulnerabilities,
            // Feature 019: Add global severity totals
            globalCritical = globalCritical,
            globalHigh = globalHigh,
            globalMedium = globalMedium,
            globalExcepted = globalExcepted,
            globalNonExcepted = globalNonExcepted,
            globalStatus = AssetInterventionStatus.worstOf(accountGroups.mapNotNull { it.status }),
            assetsNeedingAttention = accountGroups.sumOf { it.assetsNeedingAttention ?: 0 },
            thresholdDays = thresholdDays,
            lastImport = latestImport,
            dataFreshness = dataFreshness
        )
    }
}
package com.secman.service

import com.secman.crowdstrike.client.CrowdStrikeApiClient
import com.secman.crowdstrike.dto.FalconConfigDto
import com.secman.crowdstrike.dto.resolveHostIp
import com.secman.crowdstrike.dto.resolveHostIps
import com.secman.dto.CrowdStrikeVulnerabilityBatchDto
import com.secman.dto.DeviceVulnCountDto
import com.secman.dto.DomainGroupDto
import com.secman.dto.DomainSyncResultDto
import com.secman.dto.DomainVulnsSummaryDto
import com.secman.dto.VulnerabilityDto
import com.secman.repository.AssetRepository
import com.secman.repository.FalconConfigRepository
import com.secman.repository.UserMappingRepository
import com.secman.repository.VulnerabilityRepository
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Singleton
import org.slf4j.LoggerFactory
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

/**
 * Domain Vulnerabilities Service
 *
 * Provides domain-based vulnerability view for non-admin users.
 * Queries secman database for vulnerabilities based on user's domain mappings.
 *
 * Similar to AccountVulnsService but:
 * - Uses domain mappings instead of AWS account mappings
 * - Queries local database (not CrowdStrike Falcon API)
 * - Groups results by AD domain
 *
 * Access Control:
 * - Non-admin users only (admins should use System Vulns view)
 * - User must have domain mappings in UserMapping table
 * - Returns 404 if user has no domain mappings
 *
 * @see AccountVulnsService
 */
@Singleton
class DomainVulnsService(
    private val userMappingRepository: UserMappingRepository,
    private val assetRepository: AssetRepository,
    private val vulnerabilityRepository: VulnerabilityRepository,
    private val crowdStrikeApiClient: CrowdStrikeApiClient,
    private val falconConfigRepository: FalconConfigRepository,
    private val importService: CrowdStrikeVulnerabilityImportService
) {
    private val log = LoggerFactory.getLogger(DomainVulnsService::class.java)

    /**
     * Get domain-based vulnerabilities summary from secman database
     *
     * Workflow:
     * 1. Extract user email from authentication
     * 2. Verify user is NOT admin (admins use system vulns view)
     * 3. Get user's domain mappings
     * 4. Query database for assets with matching AD domains
     * 5. Query vulnerabilities for those assets
     * 6. Aggregate and group results by domain
     *
     * @param authentication User authentication context
     * @return Domain vulnerabilities summary
     * @throws IllegalStateException if user is admin
     * @throws IllegalArgumentException if user has no domain mappings
     */
    fun getDomainVulnsSummary(authentication: Authentication): DomainVulnsSummaryDto {
        // Extract user email
        val email = authentication.attributes["email"]?.toString()
            ?: throw IllegalArgumentException("User email not found in authentication context")

        log.info("Getting domain vulnerabilities from database for user: {}", email)

        // Check if user is admin
        if (authentication.roles.contains("ADMIN")) {
            throw IllegalStateException("Admin users should use System Vulnerabilities view instead")
        }

        // Get user's domain mappings
        val domains = userMappingRepository.findDistinctDomainByEmail(email)
        if (domains.isEmpty()) {
            throw IllegalArgumentException("User has no domain mappings. Please contact administrator.")
        }

        log.info("User {} has {} domain mapping(s): {}", email, domains.size, domains.joinToString(", "))

        // Query database for assets matching user's domains (case-insensitive)
        // Feature 053: Use database-level filtering instead of loading all assets
        val assetsInDomains = assetRepository.findByAdDomainInIgnoreCase(domains)

        log.info("Found {} assets in user's domains", assetsInDomains.size)

        if (assetsInDomains.isEmpty()) {
            // No assets found in user's domains - return empty summary
            return DomainVulnsSummaryDto(
                domainGroups = domains.map { domain ->
                    DomainGroupDto(
                        domain = domain,
                        devices = emptyList(),
                        totalDevices = 0,
                        totalVulnerabilities = 0,
                        totalCritical = 0,
                        totalHigh = 0,
                        totalMedium = 0,
                        totalLow = 0
                    )
                },
                totalDevices = 0,
                totalVulnerabilities = 0,
                globalCritical = 0,
                globalHigh = 0,
                globalMedium = 0,
                globalLow = 0,
                queriedAt = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
            )
        }

        // Per-asset severity counts, aggregated in SQL (latest import per asset).
        //
        // This used to be findLatestVulnerabilitiesForAssetIds(...) — one managed Vulnerability
        // entity per row, for every asset in the user's AD domains — and then counted them in
        // Kotlin. On an interactive request that scales with the multi-million-row vulnerability
        // table, the same shape that ran a 1 GB container out of heap on 2026-07-30. The counts
        // are all this endpoint ever needed, so the database returns one row per asset instead.
        val assetIds = assetsInDomains.mapNotNull { it.id }
        val countsByAssetId = if (assetIds.isNotEmpty()) {
            vulnerabilityRepository
                .countLatestVulnerabilitiesBySeverityForAssetIds(assetIds.toSet())
                .associateBy { it.assetId }
        } else {
            emptyMap()
        }

        log.info("Aggregated vulnerability counts for {} of {} assets in user's domains",
            countsByAssetId.size, assetsInDomains.size)

        // Assets with no vulnerabilities in their latest import get no aggregate row, so they
        // fall through to zeros — matching the previous `vulnsByAssetId[id] ?: emptyList()`.
        val deviceVulnCounts = assetsInDomains.map { asset ->
            val counts = countsByAssetId[asset.id]
            DeviceVulnCountDto(
                hostname = asset.name,
                ip = asset.ip,
                vulnerabilityCount = counts?.totalCount?.toInt() ?: 0,
                criticalCount = counts?.criticalCount?.toInt() ?: 0,
                highCount = counts?.highCount?.toInt() ?: 0,
                mediumCount = counts?.mediumCount?.toInt() ?: 0,
                lowCount = counts?.lowCount?.toInt() ?: 0
            )
        }.sortedByDescending { it.vulnerabilityCount }

        // Group devices by domain
        val domainGroups = createDomainGroupsFromDatabase(assetsInDomains, deviceVulnCounts)

        // Calculate global totals
        val totalCritical = deviceVulnCounts.sumOf { it.criticalCount ?: 0 }
        val totalHigh = deviceVulnCounts.sumOf { it.highCount ?: 0 }
        val totalMedium = deviceVulnCounts.sumOf { it.mediumCount ?: 0 }
        val totalLow = deviceVulnCounts.sumOf { it.lowCount ?: 0 }

        // Get latest import timestamp for "Last Synced" indicator
        val lastSyncedAt = if (assetIds.isNotEmpty()) {
            vulnerabilityRepository.findLatestImportTimestampByAssetIds(assetIds.toSet())
                ?.format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
        } else null

        return DomainVulnsSummaryDto(
            domainGroups = domainGroups,
            totalDevices = deviceVulnCounts.size,
            // Was allVulnerabilities.size; the same total, summed from the per-asset aggregates.
            totalVulnerabilities = deviceVulnCounts.sumOf { it.vulnerabilityCount },
            globalCritical = totalCritical,
            globalHigh = totalHigh,
            globalMedium = totalMedium,
            globalLow = totalLow,
            queriedAt = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME),
            lastSyncedAt = lastSyncedAt
        )
    }

    /**
     * Create domain groups from database assets
     *
     * Groups devices by their AD domain field.
     * Each domain gets its own group with its devices and vulnerability counts.
     */
    private fun createDomainGroupsFromDatabase(
        assets: List<com.secman.domain.Asset>,
        deviceVulnCounts: List<DeviceVulnCountDto>
    ): List<DomainGroupDto> {
        // Create a map of asset name to device count for quick lookup
        val deviceCountMap = deviceVulnCounts.associateBy { it.hostname }

        // Group assets by their AD domain (case-insensitive)
        val assetsByDomain = assets.groupBy { it.adDomain?.uppercase() ?: "UNKNOWN" }

        // Create domain groups
        return assetsByDomain.map { (normalizedDomain, domainAssets) ->
            // Get the original casing from the first asset
            val displayDomain = domainAssets.firstOrNull()?.adDomain ?: normalizedDomain

            // Get devices for this domain
            val devicesInDomain = domainAssets.mapNotNull { asset ->
                deviceCountMap[asset.name]
            }

            // Calculate domain-level totals
            val totalCritical = devicesInDomain.sumOf { it.criticalCount ?: 0 }
            val totalHigh = devicesInDomain.sumOf { it.highCount ?: 0 }
            val totalMedium = devicesInDomain.sumOf { it.mediumCount ?: 0 }
            val totalLow = devicesInDomain.sumOf { it.lowCount ?: 0 }

            DomainGroupDto(
                domain = displayDomain,
                devices = devicesInDomain.sortedByDescending { it.vulnerabilityCount },
                totalDevices = devicesInDomain.size,
                totalVulnerabilities = devicesInDomain.sumOf { it.vulnerabilityCount },
                totalCritical = totalCritical,
                totalHigh = totalHigh,
                totalMedium = totalMedium,
                totalLow = totalLow
            )
        }.sortedByDescending { it.totalVulnerabilities }
    }

    /**
     * Get user's domain mappings
     *
     * @param email User email address
     * @return List of domain names the user has access to
     */
    fun getUserDomains(email: String): List<String> {
        return userMappingRepository.findDistinctDomainByEmail(email)
    }

    /**
     * Sync domain vulnerabilities from CrowdStrike Falcon API to secman database
     *
     * Workflow:
     * 1. Query CrowdStrike Falcon API for all devices in the specified domain
     * 2. Convert vulnerabilities to batch format
     * 3. Import using transactional replace pattern (delete old + insert new)
     * 4. Return sync statistics
     *
     * @param domain AD domain name to sync (e.g., "CONTOSO")
     * @param triggeredBy User that triggered the sync (for audit trail)
     * @return DomainSyncResultDto with sync statistics
     * @throws IllegalStateException if CrowdStrike API is not configured
     */
    fun syncDomainFromCrowdStrike(domain: String, triggeredBy: String): DomainSyncResultDto {
        log.info("Starting domain sync from CrowdStrike: domain={}, triggeredBy={}", domain, triggeredBy)

        // Get CrowdStrike configuration
        val config = getConfiguration()

        // Query CrowdStrike for all devices in the domain
        // Use empty severity filter to get all vulnerabilities
        val response = crowdStrikeApiClient.queryVulnerabilitiesByDomains(
            domains = listOf(domain),
            severity = "",  // No severity filter - get all
            minDaysOpen = 0,
            config = config,
            limit = 10000  // High limit to get all vulnerabilities
        )

        log.info("CrowdStrike query returned {} vulnerabilities for domain {}",
            response.vulnerabilities.size, domain)

        if (response.vulnerabilities.isEmpty()) {
            log.warn("No vulnerabilities found in CrowdStrike for domain {}", domain)
            return DomainSyncResultDto(
                domain = domain,
                syncedAt = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME),
                devicesProcessed = 0,
                devicesCreated = 0,
                devicesUpdated = 0,
                vulnerabilitiesImported = 0
            )
        }

        // Group vulnerabilities by hostname to create batch DTOs
        val batches = groupVulnerabilitiesByHostname(response.vulnerabilities, domain)

        log.info("Grouped vulnerabilities into {} device batches for domain {}", batches.size, domain)

        // Import using the existing import service
        val stats = importService.importServerVulnerabilities(batches, triggeredBy, triggerRefresh = true)

        log.info("Domain sync completed: domain={}, devices={}, created={}, updated={}, vulns={}",
            domain, stats.serversProcessed, stats.serversCreated, stats.serversUpdated, stats.vulnerabilitiesImported)

        return DomainSyncResultDto(
            domain = domain,
            syncedAt = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME),
            devicesProcessed = stats.serversProcessed,
            devicesCreated = stats.serversCreated,
            devicesUpdated = stats.serversUpdated,
            vulnerabilitiesImported = stats.vulnerabilitiesImported
        )
    }

    /**
     * Get CrowdStrike Falcon configuration from database
     *
     * @return FalconConfigDto with API credentials
     * @throws IllegalStateException if configuration not found
     */
    private fun getConfiguration(): FalconConfigDto {
        val configOpt = falconConfigRepository.findActiveConfig()
        val config = if (configOpt.isPresent) {
            configOpt.get()
        } else {
            throw IllegalStateException("No active CrowdStrike configuration found. Contact administrator.")
        }

        // Map cloud region to base URL
        val baseUrl = when (config.cloudRegion) {
            "us-1" -> "https://api.crowdstrike.com"
            "us-2" -> "https://api.us-2.crowdstrike.com"
            "eu-1" -> "https://api.eu-1.crowdstrike.com"
            "us-gov-1" -> "https://api.us-gov-1.crowdstrike.com"
            "us-gov-2" -> "https://api.us-gov-2.crowdstrike.com"
            else -> "https://api.crowdstrike.com"
        }

        return FalconConfigDto(
            clientId = config.clientId,
            clientSecret = config.clientSecret,
            baseUrl = baseUrl
        )
    }

    /**
     * Group CrowdStrike vulnerabilities by hostname into batch DTOs
     *
     * @param vulnerabilities List of vulnerabilities from CrowdStrike
     * @param domain The AD domain for metadata
     * @return List of batch DTOs ready for import
     */
    private fun groupVulnerabilitiesByHostname(
        vulnerabilities: List<com.secman.crowdstrike.dto.CrowdStrikeVulnerabilityDto>,
        domain: String
    ): List<CrowdStrikeVulnerabilityBatchDto> {
        // Group by hostname
        val byHostname = vulnerabilities.groupBy { it.hostname }

        return byHostname.map { (hostname, vulns) ->
            CrowdStrikeVulnerabilityBatchDto(
                hostname = hostname,
                ip = vulns.resolveHostIp(),
                ipAddresses = vulns.resolveHostIps(),
                groups = null,  // Not available from API
                cloudAccountId = null,  // Not in this query
                cloudInstanceId = null,  // Not in this query
                adDomain = domain,
                osVersion = null,  // Not in this query
                vulnerabilities = vulns.map { vuln ->
                    // Parse daysOpen from string (e.g., "15 days" -> 15)
                    val daysOpenInt = vuln.daysOpen?.split(" ")?.firstOrNull()?.toIntOrNull() ?: 0

                    VulnerabilityDto(
                        cveId = vuln.cveId ?: "",
                        severity = vuln.severity,
                        affectedProduct = vuln.affectedProduct,
                        daysOpen = daysOpenInt,
                        patchPublicationDate = vuln.patchPublicationDate
                    )
                }
            )
        }
    }
}

