import org.slf4j.LoggerFactory
import java.io.ByteArrayOutputStream
import java.time.format.DateTimeFormatter

@Singleton
open class ApplicationRegisterExportService(
    private val repository: ApplicationRegisterRepository
) {

    private val log = LoggerFactory.getLogger(ApplicationRegisterExportService::class.java)
    private val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")
    private val dateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")

    @Transactional
    open fun exportApplications(): List<ApplicationRegister> {
        val applications = repository.findAllWithAssets()
        log.info("Found {} application register entries for export", applications.size)
        return applications
    }

    open fun writeToExcel(applications: List<ApplicationRegister>): ByteArrayOutputStream {
        log.info("Writing {} application register entries to Excel format", applications.size)

        val workbook = SXSSFWorkbook(100)
        workbook.setCompressTempFiles(true)

        try {
            val sheet = workbook.createSheet("Applications")
            val styles = createStyles(workbook)

            createHeaderRow(sheet, styles.header)
            applications.forEachIndexed { index, application ->
                createApplicationRow(sheet, index + 1, application, styles)
            }
            setFixedColumnWidths(sheet)

            val outputStream = ByteArrayOutputStream()
            workbook.write(outputStream)
            return outputStream
        } finally {
            workbook.close()
        }
    }

    private fun createStyles(workbook: Workbook): ApplicationRegisterStyles {
        val headerStyle = workbook.createCellStyle().apply {
            fillForegroundColor = IndexedColors.GREY_25_PERCENT.index
            fillPattern = FillPatternType.SOLID_FOREGROUND
            val font = workbook.createFont()
            font.bold = true
            setFont(font)
        }
        val textStyle = workbook.createCellStyle()
        val wrapTextStyle = workbook.createCellStyle().apply {
            wrapText = true
        }

        return ApplicationRegisterStyles(headerStyle, textStyle, wrapTextStyle)
    }

    private fun createHeaderRow(sheet: Sheet, headerStyle: CellStyle) {
        val headers = listOf(
            "CAR ID",
            "Name",
            "Criticality",
            "Operational Status",
            "Business Owner",
            "Application Manager",
            "Application Technology",
            "Application Architecture",
            "Last Quality Check",
            "Information Classification",
            "Processing of Personal Data",
            "ICS Relevant",
            "Export Control Relevant",
            "Operation Model",
            "Production Operating Hours",
            "Service Operating Hours",
            "Backup Recovery URL",
            "Incident Assignment Group",
            "CMDB Workspace URL",
            "Assigned Assets",
            "Notes",
            "Created At",
            "Updated At"
        )

        val row = sheet.createRow(0)
        headers.forEachIndexed { index, header ->
            row.createCell(index).apply {
                setCellValue(header)
                cellStyle = headerStyle
            }
        }
    }

    private fun createApplicationRow(
        sheet: Sheet,
        rowNum: Int,
        application: ApplicationRegister,
        styles: ApplicationRegisterStyles
    ) {
        val row = sheet.createRow(rowNum)
        val values = listOf(
            application.carId,
            application.name,
            application.criticality,
            application.operationalStatus,
            application.businessOwner,
            application.applicationManager,
            application.applicationTechnology,
            application.applicationArchitecture,
            application.lastQualityCheck?.format(dateFormatter),
            application.informationClassification,
            application.processingOfPersonalData,
            application.icsRelevant,
            application.applicationExportControlRelevant,
            application.operationModel,
            application.productionOperatingHours,
            application.serviceOperatingHours,
            application.backupRecoveryUrl,
            application.incidentAssignmentGroup,
            application.cmdbWorkspaceUrl,
            application.assets.sortedBy { it.name }.joinToString(", ") { it.name },
            application.notes,
            application.createdAt?.format(dateTimeFormatter),
            application.updatedAt?.format(dateTimeFormatter)
        )

        values.forEachIndexed { index, value ->
            row.createCell(index).apply {
                setCellValue(ExcelSanitizer.sanitize(value))
                cellStyle = if (index in WRAPPED_COLUMNS) styles.wrapText else styles.text
            }
        }
    }

    private fun setFixedColumnWidths(sheet: Sheet) {
        val widths = listOf(
            3000, 7000, 4000, 5000, 6000, 6000, 7000, 7000, 4500, 6000, 7000, 4000,
            5000, 5000, 6000, 6000, 8000, 7000, 8000, 9000, 9000, 5000, 5000
        )
        widths.forEachIndexed { index, width -> sheet.setColumnWidth(index, width) }
    }

    private data class ApplicationRegisterStyles(
        val header: CellStyle,
        val text: CellStyle,
        val wrapText: CellStyle
    )

    private companion object {
        val WRAPPED_COLUMNS = setOf(6, 7, 10, 14, 15, 16, 17, 18, 19, 20)
    }
}
package com.secman.domain

import io.micronaut.serde.annotation.Serdeable
import org.hibernate.annotations.JdbcTypeCode
import org.hibernate.type.SqlTypes
import jakarta.persistence.*
import jakarta.validation.constraints.NotBlank
import jakarta.validation.constraints.NotNull
import jakarta.validation.constraints.Size
import java.time.LocalDateTime

@Entity
@Table(name = "demand")
@Serdeable
data class Demand(
    @Id
    @GeneratedValue
    var id: Long? = null,

    @Column(nullable = false)
    @NotBlank
    @Size(max = 255)
    var title: String,

    @Column(length = 1024)
    var description: String? = null,

    @JdbcTypeCode(SqlTypes.VARCHAR)
    @Enumerated(EnumType.STRING)
    @Column(name = "demand_type", nullable = false)
    @NotNull
    var demandType: DemandType,

    @ManyToOne
    @JoinColumn(name = "existing_asset_id")
    var existingAsset: Asset? = null,

    @Column(name = "new_asset_name")
    @Size(max = 255)
    var newAssetName: String? = null,

    @Column(name = "new_asset_type")
    @Size(max = 100)
    var newAssetType: String? = null,

    @Column(name = "new_asset_ip")
    @Size(max = 45)
    var newAssetIp: String? = null,

    @Column(name = "new_asset_owner")
    @Size(max = 255)
    var newAssetOwner: String? = null,

    @Column(name = "new_asset_description", length = 1024)
    var newAssetDescription: String? = null,

    @Column(name = "business_justification", length = 2048)
    var businessJustification: String? = null,

    @JdbcTypeCode(SqlTypes.VARCHAR)
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    var priority: Priority = Priority.MEDIUM,

    @JdbcTypeCode(SqlTypes.VARCHAR)
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    var status: DemandStatus = DemandStatus.PENDING,

    @ManyToOne
    @JoinColumn(name = "requestor_id", nullable = false)
    @NotNull
    var requestor: User,

    @ManyToOne
    @JoinColumn(name = "approver_id")
    var approver: User? = null,

    @Column(name = "requested_date", nullable = false)
    var requestedDate: LocalDateTime = LocalDateTime.now(),

    @Column(name = "approved_date")
    var approvedDate: LocalDateTime? = null,

    @Column(name = "rejection_reason", length = 1024)
    var rejectionReason: String? = null,

    @Column(name = "created_at", nullable = false, updatable = false)
    var createdAt: LocalDateTime? = null,

    @Column(name = "updated_at", nullable = false)
    var updatedAt: LocalDateTime? = null
) {
    @PrePersist
    fun onCreate() {
        val now = LocalDateTime.now()
        createdAt = now
        updatedAt = now
        if (requestedDate == LocalDateTime.MIN) {
            requestedDate = now
        }
    }

    @PreUpdate
    fun onUpdate() {
        updatedAt = LocalDateTime.now()
    }

    /**
     * Validates that the demand has proper asset information based on type
     */
    fun validateAssetInformation(): Boolean {
        return when (demandType) {
            DemandType.CHANGE -> existingAsset != null
            DemandType.CREATE_NEW -> {
                !newAssetName.isNullOrBlank() &&
                !newAssetType.isNullOrBlank() &&
                !newAssetOwner.isNullOrBlank()
            }
        }
    }

    /**
     * Gets the asset name regardless of demand type
     */
    fun getAssetName(): String {
        return when (demandType) {
            DemandType.CHANGE -> existingAsset?.name ?: "Unknown Asset"
            DemandType.CREATE_NEW -> newAssetName ?: "Unnamed Asset"
        }
    }

    /**
     * Gets the asset type regardless of demand type
     */
    fun getAssetType(): String {
        return when (demandType) {
            DemandType.CHANGE -> existingAsset?.type ?: "Unknown"
            DemandType.CREATE_NEW -> newAssetType ?: "Unknown"
        }
    }

    /**
     * Gets the asset owner regardless of demand type
     */
    fun getAssetOwner(): String {
        return when (demandType) {
            DemandType.CHANGE -> existingAsset?.owner ?: "Unknown"
            DemandType.CREATE_NEW -> newAssetOwner ?: "Unknown"
        }
    }

    override fun toString(): String {
        return "Demand(id=$id, title='$title', type=$demandType, status=$status)"
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is Demand) return false
        return id != null && id == other.id
    }

    override fun hashCode(): Int {
        return id?.hashCode() ?: 0
    }
}

@Serdeable
enum class DemandType {
    CHANGE,     // Modifying an existing asset
    CREATE_NEW  // Creating a new asset
}

@Serdeable
enum class Priority {
    LOW,
    MEDIUM,
    HIGH,
    CRITICAL
}

@Serdeable
enum class DemandStatus {
    PENDING,      // Waiting for approval
    APPROVED,     // Approved and ready for risk assessment
    REJECTED,     // Rejected by approver
    IN_PROGRESS,  // Risk assessment in progress
    COMPLETED     // Risk assessment completed
