/**
 * REST Controller for Outdated Assets view
 *
 * Provides paginated list of assets with overdue vulnerabilities
 * Access: ADMIN and VULN roles only
 * Returns workgroup-filtered results for VULN users
 */
@Controller("/api/outdated-assets")
@Secured(SecurityRule.IS_AUTHENTICATED)
class OutdatedAssetController(
    private val outdatedAssetService: OutdatedAssetService
) {
    private val log = LoggerFactory.getLogger(OutdatedAssetController::class.java)

    data class ErrorResponse(val error: String)

    /**
     * GET /api/outdated-assets
     *
     * Returns paginated list of outdated assets with optional filtering
     *
     * Access Control:
     * - ADMIN role: sees all outdated assets
     * - VULN role: sees only assets from assigned workgroups
     * - Other roles: 403 Forbidden
     *
     * Query Parameters:
     * - page (optional): Page number (default: 0)
     * - size (optional): Page size (default: 20)
     * - sort (optional): Sort field and direction (e.g., "oldestVulnDays,desc")
     * - searchTerm (optional): Search by asset name (case-insensitive)
     * - minSeverity (optional): Minimum severity filter (CRITICAL, HIGH, MEDIUM, LOW)
     * - adDomain (optional): AD domain filter (case-insensitive exact match)
     *
     * Response:
     * - 200 OK: Paginated list of outdated assets
     * - 401 Unauthorized: Not authenticated
     * - 403 Forbidden: User lacks ADMIN or VULN role
     */
    @Get
    @Secured("ADMIN", "VULN")
    fun getOutdatedAssets(
        authentication: Authentication,
        @QueryValue(defaultValue = "") searchTerm: String?,
        @QueryValue(defaultValue = "") minSeverity: String?,
        @QueryValue(defaultValue = "") adDomain: String?,
        pageable: Pageable
    ): HttpResponse<Map<String, Any>> {
        // Validate user has required role
        val hasRequiredRole = authentication.hasAnyRole("ADMIN", "VULN")
        if (!hasRequiredRole) {
            return HttpResponse.status(HttpStatus.FORBIDDEN)
        }

        // Get outdated assets with workgroup filtering applied by service
        val page = outdatedAssetService.getOutdatedAssets(
            authentication = authentication,
            searchTerm = searchTerm.takeIf { !it.isNullOrBlank() },
            minSeverity = minSeverity.takeIf { !it.isNullOrBlank() },
            adDomain = adDomain.takeIf { !it.isNullOrBlank() },
            pageable = pageable
        )

        // Map to DTOs
        val dtoPage = page.map { OutdatedAssetDto.from(it) }

        return HttpResponse.ok(mapOf(
            "content" to dtoPage.content,
            "totalElements" to dtoPage.totalSize,
            "totalPages" to dtoPage.totalPages,
            "size" to dtoPage.size,
            "number" to dtoPage.pageNumber
        ))
    }

    /**
     * GET /api/outdated-assets/ad-domains
     *
     * Returns distinct AD domain values for the filter dropdown
     *
     * Response:
     * - 200 OK: { "adDomains": ["domain1.local", "domain2.local"] }
     */
    @Get("/ad-domains")
    @Secured("ADMIN", "VULN")
    fun getAdDomains(authentication: Authentication): HttpResponse<Map<String, Any>> {
        // Validate user has required role
        val hasRequiredRole = authentication.hasAnyRole("ADMIN", "VULN")
        if (!hasRequiredRole) {
            return HttpResponse.status(HttpStatus.FORBIDDEN)
        }

        val domains = outdatedAssetService.getDistinctAdDomains()
        return HttpResponse.ok(mapOf("adDomains" to domains))
    }

    /**
     * GET /api/outdated-assets/last-refresh
     *
     * Returns the timestamp of the last materialized view refresh
     *
     * Response:
     * - 200 OK: { "lastRefreshTimestamp": "2024-10-26T14:30:00" }
     * - 204 No Content: No refresh has occurred yet
     */
    @Get("/last-refresh")
    @Secured("ADMIN", "VULN")
    fun getLastRefreshTimestamp(authentication: Authentication): HttpResponse<Map<String, Any>> {
        // Validate user has required role
        val hasRequiredRole = authentication.hasAnyRole("ADMIN", "VULN")
        if (!hasRequiredRole) {
            return HttpResponse.status(HttpStatus.FORBIDDEN)
        }

        val timestamp = outdatedAssetService.getLastRefreshTimestamp()

        return if (timestamp != null) {
            HttpResponse.ok(mapOf("lastRefreshTimestamp" to timestamp))
        } else {
            HttpResponse.noContent()
        }
    }

    /**
     * GET /api/outdated-assets/count
     *
     * Returns count of outdated assets visible to the user (workgroup-filtered)
     *
     * Response:
     * - 200 OK: { "count": 42 }
     */
    @Get("/count")
    @Secured("ADMIN", "VULN")
    fun getOutdatedAssetsCount(authentication: Authentication): HttpResponse<Map<String, Any>> {
        // Validate user has required role
        val hasRequiredRole = authentication.hasAnyRole("ADMIN", "VULN")
        if (!hasRequiredRole) {
            return HttpResponse.status(HttpStatus.FORBIDDEN)
        }

        val count = outdatedAssetService.countOutdatedAssets(authentication)

        return HttpResponse.ok(mapOf("count" to count))
    }

    /**
     * GET /api/outdated-assets/export
     *
     * Export outdated assets to Excel with the same filters as the list view
     *
     * Query Parameters:
     * - searchTerm (optional): Search by asset name
     * - minSeverity (optional): Minimum severity filter
     * - adDomain (optional): AD domain filter
     *
     * Response:
     * - 200 OK: Excel file (.xlsx)
     * - 403 Forbidden: User lacks ADMIN or VULN role
     */
    @Get("/export")
    @Secured("ADMIN", "VULN")
    fun exportOutdatedAssets(
        authentication: Authentication,
        @QueryValue(defaultValue = "") searchTerm: String?,
        @QueryValue(defaultValue = "") minSeverity: String?,
        @QueryValue(defaultValue = "") adDomain: String?
    ): HttpResponse<*> {
        val hasRequiredRole = authentication.hasAnyRole("ADMIN", "VULN")
        if (!hasRequiredRole) {
            return HttpResponse.status<Any>(HttpStatus.FORBIDDEN)
        }

        return try {
            log.info("Outdated assets export request from user: {}", authentication.name)

            val outputStream = outdatedAssetService.exportOutdatedAssets(
                authentication = authentication,
                searchTerm = searchTerm.takeIf { !it.isNullOrBlank() },
                minSeverity = minSeverity.takeIf { !it.isNullOrBlank() },
                adDomain = adDomain.takeIf { !it.isNullOrBlank() }
            )

            val dateStr = java.time.LocalDate.now().toString()
            val filename = "outdated_assets_$dateStr.xlsx"

            log.info("Outdated assets export successful for user: {}", authentication.name)

            HttpResponse.ok(outputStream.toByteArray())
                .header("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
                .header("Content-Disposition", "attachment; filename=\"$filename\"")
        } catch (e: Exception) {
            log.error("Outdated assets export failed for user: {}", authentication.name, e)
            HttpResponse.serverError<ErrorResponse>()
                .body(ErrorResponse("An internal error occurred"))
        }
    }

    /**
     * GET /api/outdated-assets/{id}
     *
     * Get single outdated asset by ID with workgroup-based access control
     *
     * Access Control:
     * - ADMIN role: can access any outdated asset
     * - VULN role: can only access assets from assigned workgroups
     *
     * Response:
     * - 200 OK: OutdatedAssetDto
     * - 404 Not Found: Asset not found or user lacks access
     * - 403 Forbidden: User lacks ADMIN or VULN role
     */
    @Get("/{id}")
    @Secured("ADMIN", "VULN")
    fun getOutdatedAssetById(
        id: Long,
        authentication: Authentication
    ): HttpResponse<OutdatedAssetDto> {
        // Validate user has required role
        val hasRequiredRole = authentication.hasAnyRole("ADMIN", "VULN")
        if (!hasRequiredRole) {
            return HttpResponse.status(HttpStatus.FORBIDDEN)
        }

        // Get asset with access control
        val asset = outdatedAssetService.getOutdatedAssetById(id, authentication)
            ?: return HttpResponse.notFound()

        // Map to DTO
        val dto = OutdatedAssetDto.from(asset)

        return HttpResponse.ok(dto)
    }

    /**
     * GET /api/outdated-assets/{id}/vulnerabilities
     *
     * Get paginated list of vulnerabilities for an outdated asset
     *
     * Access Control:
     * - Requires user to have access to the outdated asset (checked via getOutdatedAssetById)
     *
     * Query Parameters:
     * - page, size, sort (standard pagination)
     *
     * Response:
     * - 200 OK: Page of vulnerabilities
     * - 404 Not Found: Asset not found or user lacks access
     * - 403 Forbidden: User lacks ADMIN or VULN role
     */
    @Get("/{id}/vulnerabilities")
    @Secured("ADMIN", "VULN")
    fun getAssetVulnerabilities(
        id: Long,
        authentication: Authentication,
        pageable: Pageable
    ): HttpResponse<Map<String, Any>> {
        // Validate user has required role
        val hasRequiredRole = authentication.hasAnyRole("ADMIN", "VULN")
        if (!hasRequiredRole) {
            return HttpResponse.status(HttpStatus.FORBIDDEN)
        }

        // First check if user has access to the outdated asset
        val outdatedAsset = outdatedAssetService.getOutdatedAssetById(id, authentication)
            ?: return HttpResponse.notFound()

        // Get vulnerabilities for the asset
        val vulnerabilities = outdatedAssetService.getVulnerabilitiesForAsset(
            outdatedAsset.assetId,
            pageable
        )

        return HttpResponse.ok(mapOf(
            "content" to vulnerabilities.content,
            "totalElements" to vulnerabilities.totalSize,
            "totalPages" to vulnerabilities.totalPages,
            "size" to vulnerabilities.size,
            "number" to vulnerabilities.pageNumber
        ))
    }
}
package com.secman.service

import com.secman.domain.OutdatedAssetMaterializedView
import com.secman.util.ExcelSanitizer
import com.secman.domain.Vulnerability
import com.secman.repository.AssetRepository
import com.secman.repository.OutdatedAssetMaterializedViewRepository
import com.secman.repository.VulnerabilityRepository
import io.micronaut.data.model.Page
import io.micronaut.data.model.Pageable
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Singleton
import org.apache.poi.ss.usermodel.FillPatternType
import org.apache.poi.ss.usermodel.IndexedColors
import org.apache.poi.xssf.streaming.SXSSFWorkbook
import org.slf4j.LoggerFactory
import java.io.ByteArrayOutputStream

/**
 * Service for accessing outdated assets with workgroup-based access control
 *
 * Responsibilities:
 * - Query materialized view with pagination, sorting, filtering
 * - Apply workgroup-based access control (ADMIN sees all, VULN sees assigned workgroups only)
 * - Support search and severity filtering
 */
@Singleton
class OutdatedAssetService(
    private val outdatedAssetRepository: OutdatedAssetMaterializedViewRepository,
    private val vulnerabilityRepository: VulnerabilityRepository,
    private val assetRepository: AssetRepository,
    private val assetFilterService: AssetFilterService
) {
    private val log = LoggerFactory.getLogger(OutdatedAssetService::class.java)

    /**
     * Compute the unified-access-control set of asset IDs visible to the user.
     *
     * Returns null for ADMIN (universal access — no filtering).
     * Otherwise delegates to AssetFilterService which applies:
     *   workgroup membership, ownership, AWS account / domain mappings,
     *   AWS account sharing, manual creation, scan upload.
     *
     * The materialized-view SQL only filters by workgroup_ids and treats
     * blank workgroup_ids as "visible to everyone", so this post-filter is
     * mandatory to enforce real access control on top of the view query.
     */
    private fun accessibleAssetIds(authentication: Authentication): Set<Long>? {
        if (authentication.roles.contains("ADMIN")) return null
        return assetFilterService.getAccessibleAssets(authentication)
            .mapNotNull { it.id }
            .toSet()
    }

    /**
     * Get outdated assets with workgroup-based access control
     *
     * Access Control:
     * - ADMIN role: sees all outdated assets (no filtering)
     * - VULN role: sees only assets from assigned workgroups
     * - No VULN/ADMIN: unauthorized (handled by controller @Secured)
     *
     * @param authentication Current user authentication context
     * @param searchTerm Optional search term for asset name (case-insensitive)
     * @param minSeverity Optional minimum severity filter (CRITICAL, HIGH, MEDIUM, LOW)
     * @param adDomain Optional AD domain filter (case-insensitive exact match)
     * @param pageable Pagination and sorting parameters
     * @return Page of outdated assets visible to the user
     */
    fun getOutdatedAssets(
        authentication: Authentication,
        searchTerm: String? = null,
        minSeverity: String? = null,
        adDomain: String? = null,
        pageable: Pageable
    ): Page<OutdatedAssetMaterializedView> {
        // Extract user's workgroup IDs from authentication attributes
        val workgroupIds = extractWorkgroupIds(authentication)

        // Check if user has ADMIN role - if so, they see everything
        val isAdmin = authentication.roles.contains("ADMIN")

        // Build workgroup filter parameter — kept as a coarse SQL pre-filter
        // for performance; the authoritative access decision is the unified
        // post-filter below.
        val workgroupFilter = if (isAdmin) {
            null
        } else {
            workgroupIds?.joinToString(",")
        }

        // Query repository with filters
        // Create pageable without sorting to avoid JPQL query issues
        val unsortedPageable = Pageable.from(pageable.number, pageable.size)

        val rawPage = outdatedAssetRepository.findOutdatedAssets(
            workgroupId = workgroupFilter,
            searchTerm = searchTerm,
            minSeverity = minSeverity,
            adDomain = adDomain,
            pageable = unsortedPageable
        )

        // Apply unified access control. The SQL filter alone is permissive
        // (treats workgroup_ids="" / NULL as visible-to-all), which leaks
        // unassigned assets across users. AssetFilterService implements
        // owner / AWS-account / domain / sharing rules so the result here
        // matches what the user can see via /api/assets and other endpoints.
        val accessible = accessibleAssetIds(authentication) ?: return rawPage

        val filteredContent = rawPage.content.filter { accessible.contains(it.assetId) }
        if (filteredContent.size == rawPage.content.size) return rawPage
        return io.micronaut.data.model.Page.of(filteredContent, unsortedPageable, filteredContent.size.toLong())
    }

    /**
     * Extract workgroup IDs from authentication context
     *
     * Workgroup IDs are stored in authentication attributes as "workgroupIds"
     * Expected format: List<Long>
     *
     * @param authentication User authentication context
     * @return List of workgroup IDs or null if not present
     */
    private fun extractWorkgroupIds(authentication: Authentication): List<Long>? {
        val workgroupIdsAttr = authentication.attributes["workgroupIds"] ?: return null

        return when (workgroupIdsAttr) {
            is List<*> -> workgroupIdsAttr.filterIsInstance<Long>()
            is Collection<*> -> workgroupIdsAttr.filterIsInstance<Long>()
            else -> null
        }
    }

    /**
     * Get the latest refresh timestamp
     *
     * @return Latest timestamp from materialized view, or null if no data
     */
    fun getLastRefreshTimestamp(): java.time.LocalDateTime? {
        return outdatedAssetRepository.findLatestCalculatedAt()
    }

    /**
     * Get distinct AD domains for filter dropdown
     *
     * Queries the Asset table directly to get all AD domains in the system,
     * rather than the materialized view which may not be refreshed.
     *
     * @return List of unique AD domain values, ordered alphabetically
     */
    fun getDistinctAdDomains(): List<String> {
        return assetRepository.findDistinctAdDomains()
    }

    /**
     * Count total outdated assets visible to user
     *
     * @param authentication Current user authentication context
     * @return Total count respecting workgroup access control
     */
    fun countOutdatedAssets(authentication: Authentication): Long {
        val isAdmin = authentication.roles.contains("ADMIN")

        if (isAdmin) {
            return outdatedAssetRepository.count()
        }

        // Non-admin: count via the authoritative unified access set rather
        // than the SQL workgroup filter (which incorrectly counts assets
        // with no workgroups for users with no workgroups). Pull all view
        // rows the user can see and count them — bounded by the size of
        // the user's accessible asset set.
        val accessible = accessibleAssetIds(authentication) ?: return outdatedAssetRepository.count()
        if (accessible.isEmpty()) return 0L

        val workgroupIds = extractWorkgroupIds(authentication)
        val workgroupFilter = workgroupIds?.joinToString(",")
        val candidatePage = outdatedAssetRepository.findOutdatedAssets(
            workgroupId = workgroupFilter,
            searchTerm = null,
            minSeverity = null,
            adDomain = null,
            pageable = Pageable.from(0, 100_000)
        )
        return candidatePage.content.count { accessible.contains(it.assetId) }.toLong()
    }

    /**
     * Get single outdated asset by ID with access control
     *
     * @param id Outdated asset materialized view ID
     * @param authentication Current user authentication context
     * @return Outdated asset or null if not found or unauthorized
     */
    fun getOutdatedAssetById(
        id: Long,
        authentication: Authentication
    ): OutdatedAssetMaterializedView? {
        val asset = outdatedAssetRepository.findById(id).orElse(null) ?: return null

        if (authentication.roles.contains("ADMIN")) return asset

        // Use unified access control. The previous workgroup-only check
        // had an explicit "no workgroups → allow" backward-compat bypass
        // that exposed every unassigned asset to every VULN user.
        val accessible = accessibleAssetIds(authentication) ?: return asset
        return if (accessible.contains(asset.assetId)) asset else null
    }

    /**
     * Get vulnerabilities for an outdated asset
     *
     * @param assetId The actual asset ID (not materialized view ID)
     * @param pageable Pagination parameters
     * @return Page of vulnerabilities for the asset
     */
    fun getVulnerabilitiesForAsset(
        assetId: Long,
        pageable: Pageable
    ): Page<Vulnerability> {
        return vulnerabilityRepository.findByAssetId(assetId, pageable)
    }

    /**
     * Defense-in-depth variant: verify the user can access the asset before
     * returning its vulnerabilities. Prefer this over [getVulnerabilitiesForAsset]
     * for any new caller — the unchecked variant is retained only for the
     * existing controller path that already validates access via
     * [getOutdatedAssetById] immediately before calling.
     */
    fun getVulnerabilitiesForAssetWithAuth(
        assetId: Long,
        authentication: Authentication,
        pageable: Pageable
    ): Page<Vulnerability>? {
        if (!authentication.roles.contains("ADMIN")) {
            val accessible = accessibleAssetIds(authentication)
            if (accessible != null && !accessible.contains(assetId)) return null
        }
        return vulnerabilityRepository.findByAssetId(assetId, pageable)
    }

    /**
     * Export outdated assets to Excel with the same filters as the list view
     *
     * @param authentication Current user authentication context
     * @param searchTerm Optional search term for asset name
     * @param minSeverity Optional minimum severity filter
     * @param adDomain Optional AD domain filter
     * @return ByteArrayOutputStream containing the Excel workbook
     */
    fun exportOutdatedAssets(
        authentication: Authentication,
        searchTerm: String? = null,
        minSeverity: String? = null,
        adDomain: String? = null
    ): ByteArrayOutputStream {
        // Fetch all matching assets (large page to get everything)
        val page = getOutdatedAssets(
            authentication = authentication,
            searchTerm = searchTerm,
            minSeverity = minSeverity,
            adDomain = adDomain,
            pageable = Pageable.from(0, 100_000)
        )
        val assets = page.content

        log.info("Exporting {} outdated assets to Excel for user: {}", assets.size, authentication.name)

        val workbook = SXSSFWorkbook(100)
        workbook.setCompressTempFiles(true)

        try {
            val sheet = workbook.createSheet("Outdated Assets")

            // Header style
            val headerStyle = workbook.createCellStyle().apply {
                fillForegroundColor = IndexedColors.GREY_25_PERCENT.index
                fillPattern = FillPatternType.SOLID_FOREGROUND
                val font = workbook.createFont()
                font.bold = true
                setFont(font)
            }

            // Header row
            val headerRow = sheet.createRow(0)
            val headers = listOf(
                "Asset Name", "Asset Type", "AD Domain",
                "Total Overdue", "Critical", "High", "Medium", "Low",
                "Oldest Vuln (Days)", "Oldest Vuln ID"
            )
            headers.forEachIndexed { index, header ->
                headerRow.createCell(index).apply {
                    setCellValue(header)
                    cellStyle = headerStyle
                }
            }

            // Data rows
            assets.forEachIndexed { index, asset ->
                val row = sheet.createRow(index + 1)
                row.createCell(0).setCellValue(ExcelSanitizer.sanitize(asset.assetName))
                row.createCell(1).setCellValue(ExcelSanitizer.sanitize(asset.assetType))
                row.createCell(2).setCellValue(ExcelSanitizer.sanitize(asset.adDomain))
                row.createCell(3).setCellValue(asset.totalOverdueCount.toDouble())
                row.createCell(4).setCellValue(asset.criticalCount.toDouble())
                row.createCell(5).setCellValue(asset.highCount.toDouble())
                row.createCell(6).setCellValue(asset.mediumCount.toDouble())
                row.createCell(7).setCellValue(asset.lowCount.toDouble())
                row.createCell(8).setCellValue(asset.oldestVulnDays.toDouble())
                row.createCell(9).setCellValue(ExcelSanitizer.sanitize(asset.oldestVulnId))
            }

            // Column widths
            sheet.setColumnWidth(0, 40 * 256)  // Asset Name
            sheet.setColumnWidth(1, 15 * 256)  // Asset Type
            sheet.setColumnWidth(2, 25 * 256)  // AD Domain
            sheet.setColumnWidth(3, 15 * 256)  // Total Overdue
            sheet.setColumnWidth(4, 12 * 256)  // Critical
            sheet.setColumnWidth(5, 12 * 256)  // High
            sheet.setColumnWidth(6, 12 * 256)  // Medium
            sheet.setColumnWidth(7, 12 * 256)  // Low
            sheet.setColumnWidth(8, 18 * 256)  // Oldest Vuln Days
            sheet.setColumnWidth(9, 20 * 256)  // Oldest Vuln ID

            val outputStream = ByteArrayOutputStream()
            workbook.write(outputStream)
            return outputStream
        } finally {
            @Suppress("DEPRECATION") workbook.dispose()
        }
    }
}
"}

