                        persisted = {
                            queryService.queryFromDatabase(
                                sanitizedHostname, severity, product, pageSize, pageNumber
                            )
                        }
                    )
                } else {
                    queryService.queryVulnerabilities(
                        hostname = sanitizedHostname,
                        severity = severity,
                        product = product,
                        limit = pageSize,
                        page = pageNumber
                    )
                }
            }

            log.info(
