        } catch (e: CrowdStrikeError) {
            log.error("CrowdStrike error: {}", e.message)
            HttpResponse.status<Map<String, String>>(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(mapOf("error" to "An error occurred communicating with CrowdStrike"))
