        @Nullable @QueryValue page: Int?,
        @Nullable @QueryValue size: Int?
    ): HttpResponse<PaginatedProductSystemsResponse> {
        // Decode URL-encoded product name
        val decodedProduct = URLDecoder.decode(product, StandardCharsets.UTF_8)

