const s=load("scan");
const threatModel={
 summary:"SecMan is a Kotlin/Micronaut and React application exposing asset inventory, vulnerabilities, assessments, exports and notifications over REST and delegated MCP. Asset authorization is the union of enabled direct workgroup asset/AWS-account/AD-domain grants, personal email-keyed AWS/AD mappings, and selected directional AWS sharing. ADMIN and SECCHAMPION have global access. Secondary projections and outbound notifications must respect the same current actor or recipient scope.",
 assets:[
 "Asset hostnames, IDs, IP addresses, URI, owner, cloud account/instance and AD domain, plus associated vulnerabilities and scans (AssetController.kt:181-208; AssetFilterService.kt:120-179).",
 "Grant integrity: enabled workgroups and explicit asset/account/domain joins, personal email mappings, and directional account sharing. Parent groups and owner/creator/uploader metadata are not grants (AssetAccessSql.kt:8-51).",
 "Current enabled user identity, roles and email, and MCP key owner/delegate bindings (CurrentIdentityRule.kt:19-29; McpDelegationService.kt:224-265).",
 "Exported data and queued export files, stable requester identity and captured scope digest (AssetExportService.kt:48-56; VulnerabilityExportJobService.kt:167-223,327-347).",
 "Confidential asset and EOL information delivered by SMTP; recipient scope must be independently authorized (AwsAccountRecipientResolver.kt:32-52; EolNotificationService.kt:150-166)."
 ],
 trustBoundaries:[
 "Authenticated browser requests cross CurrentIdentityRule and endpoint role gates; each REST consumer must apply current AssetFilterService scope before returning linked asset information, aggregating or paginating (AssetController.kt:305-342,417-429,603-619,989-994).",
 "Central authorization crosses into database queries: global access is limited to ADMIN/SECCHAMPION and ordinary users receive the explicit union, without workgroup hierarchy inheritance (AssetFilterService.kt:100-111; AssetAccessSql.kt:8-51).",
 "MCP keys cross into an enabled, explicitly allowed delegate and the intersection of key/role permissions; scoped tools rebuild current accessible IDs (McpDelegationService.kt:224-265; McpAccessControlService.kt:55-93).",
 "Ordinary asset metadata editing is separate from grant editing; workgroup account/domain grants require GrantAuthority, and personal mapping administration is ADMIN-gated (GrantAuthority.kt:3-6; AssetController.kt:616-619).",
 "Account sharing creation requires the caller to be its source and to hold the selected personal account mappings; empty selection includes future source mappings. Update/delete are globally privileged (AwsAccountSharingController.kt:91-104,203-205,298-300).",
 "Queued exports capture actor and scope; processing and download revalidate identity and scope, with path containment checks. Default storage is a relative exports directory and may be configured; deployment filesystem isolation was not checked (VulnerabilityExportJobService.kt:62,167-223,327-347,714-715).",
 "Notifications cross from an authorized sender to independent recipients. Whole-account mappings are distinct from access to one asset; owner/creator/uploader metadata currently introduces an unauthorized recipient path (EolNotificationService.kt:150-166; EolBroadcastRecipientResolver.kt:58-74).",
 "Task and assessment history crosses into linked asset/account projections. A historical requestor or respondent relation does not establish current inventory access (DemandController.kt:139-218; UserDashboardService.kt:87-94,155-175)."
 ],
 attackerCapabilities:[
 "An enabled ordinary user can call authenticated routes directly, enumerate identifiers and supply filters, including routes that the UI does not expose.",
 "A scoped VULN user can invoke hostname/instance vulnerability lookups and request arbitrary outdated-asset pages; RISK/REPORT users can invoke their role-gated reports.",
 "A user with permitted asset editing can set metadata but cannot thereby create an asset grant. A source user can create sharing only under the current personal-account authority checks.",
 "A permitted MCP caller controls tool arguments but cannot select an arbitrary unbound or disabled delegate.",
 "A formerly authorized requestor/respondent or metadata-associated email recipient can receive residual linked information after grants or assignments change; legitimate administrator mail sending is sufficient to trigger the notification path.",
 "Old JWT identity changes are rejected and queued exports fail closed after scope changes; these controls were verified in source, not runtime."
 ],
 securityObjectives:[
 "Ordinary users see only assets authorized by current enabled direct workgroups, personal AWS/AD mappings and documented selected incoming sharing; ADMIN/SECCHAMPION retain explicit global access.",
 "Every asset-derived response, application projection, risk report, option list, count, export and email respects the current actor or recipient scope.",
 "Revocation is effective on subsequent reads and deliveries; ownership, creation/upload history, hierarchy and historical task relations confer no implicit asset access.",
 "Whole-account authority is distinct from permission to one asset, and workgroup membership does not inherit another member's personal mappings.",
 "Current active assessment assignments may expose the minimum intended task context, but revoked assignments must not retain that context or usable tokens."
 ],
 assumptions:[
 "Review is static and read-only against the current dirty working tree on dev. No source edits, application requests, credentials, DB mutations, browser tests, SMTP tests or service restarts were performed for this review.",
 "Documented workgroup account/domain grants, selected incoming sharing and ADMIN/SECCHAMPION global access are treated as approved policy exceptions to a literal reading of only personally mapped accounts/domains.",
 "Personal mappings are email-keyed; stored user_id, mapping status and appliedAt are not the authority checks. Pending mappings and email reassignment behavior need policy confirmation before changing this contract.",
 "Sharing self-creation exists while update/delete are ADMIN/SECCHAMPION-only. Documentation and the intended ability of a source user to revoke sharing require alignment; no authority bypass was inferred solely from this workflow mismatch.",
 "Existing cache/ownership comments can be stale; current code and query predicates take precedence. AccessibleAssetIdsCache is request-scoped and MCP checks use live scope.",
 "The scoped authorization review is not an exhaustive review of all repository files or all OWASP vulnerability categories. Deployment exposure, mail transport, export storage isolation and runtime behavior were not independently exercised.",
 "The ten retained findings are independently traced source paths with concrete reachable role/recipient prerequisites; no unsupported exploit reproduction is claimed."
 ]};
store("threatModel",threatModel);
const coverage=load("finalCoverage");
coverage.includePaths=["."];
coverage.excludePaths=[];
coverage.mode="standard";
coverage.inventoryStrategy="Repository-wide inventory followed by source review of asset authorization and derived projections across REST, MCP, frontend consumers, exports, notifications and assignment revocation; not every repository file reviewed.";
coverage.openQuestions=[
 "Are selected incoming AWS sharing, explicit workgroup AWS/AD grants, and ADMIN/SECCHAMPION global access all intended exceptions to the latest wording?",
 "Should personal mappings remain email-keyed including pending rows, or be bound to a stable user identity?",
 "Should source users be able to revoke self-created sharing? Current creation and update/delete privileges differ.",
 "Runtime REST/MCP/UI/export/SMTP regression execution remains outstanding; findings are source validated."
];
coverage.explicitExclusions=[
 {pattern:"Security classes unrelated to asset visibility",reason:"This scan is restricted to the user-requested asset-authorization policy review."},
 {pattern:"Runtime reproduction and deployment validation",reason:"Read-only source review; no live requests, database changes, browser tests, SMTP delivery or deployment checks were executed."}
];
coverage.surfaces.push(
 {label:"Secondary REST projections, reports, options and pagination",disposition:"reported",notes:"Application detail/export, CrowdStrike lookups, risk reports, global filter metadata, asset-existence response differences and outdated pagination have retained findings. Asset rows in the main overview remain scoped."},
 {label:"Demand and assessment assignment revocation",disposition:"reported",notes:"Linked demand assets and the approved-demand picker bypass current scope. Dashboard legacy respondent state retains basis metadata after full-to-scoped assignment replacement and scoped revocation; old workflow tokens remain rejected."},
 {label:"EOL notification recipient confidentiality",disposition:"reported",notes:"Whole-account resolver is appropriately scoped, but independent owner/creator/uploader recipients can receive asset details without current grants."},
 {label:"Regression tests and frontend consumers",disposition:"needs_follow_up",notes:"Existing isolation, identity, grant, MCP and export tests inspected in source. Application/EOL/dashboard tests do not cover the confirmed hidden-asset or revocation cases. No tests executed; proposed checks are attached to each finding."}
);
store("finalCoverage",coverage);
text(await tools.mcp__codex_security__update_codex_security_scan_progress({scanId:s.scanId,phase:"attack_path",phaseItemsTotal:10,phaseItemsCompleted:10,phaseProgressUnit:"validated_findings",reportableFindingsCount:10,reviewItemsTotal:4,reviewItemsCompleted:4}));
text(await tools.mcp__codex_security__record_codex_security_scan_draft({scanId:s.scanId,complete:false,threatModel,findings:load("findings"),coverage}));

